      "STATOR ET ROTOR": { en:"STATOR AND ROTOR", de:"STATOR UND ROTOR", es:"ESTÁTOR Y ROTOR", it:"STATORE E ROTORE", br:"ESTATOR E ROTOR", pt:"ESTATOR E ROTOR", pl:"STOJAN I WIRNIK", ru:"СТАТОР И РОТОР", ja:"ステーター​と​ローター" },
