      "FAITES D'ABORD L'ETAPE {0}": { en:"FIRST COMPLETE THIS STEP: {0}", de:"ERST DIESEN SCHRITT ABSCHLIESSEN: {0}", es:"TERMINE PRIMERO ESTE PASO: {0}", it:"PRIMA COMPLETA QUESTO PASSO: {0}", br:"PRIMEIRO CONCLUA ESTA ETAPA: {0}", pt:"PRIMEIRO CONCLUA ESTA ETAPA: {0}", pl:"NAJPIERW UKOŃCZ ETAP: {0}", ru:"СНАЧАЛА ЗАВЕРШИТЕ ЭТАП: {0}", ja:"先に​この​ステップを​完了：{0}" },
