      "A LA CONDUITE : {0} %": { en:"WHEN DRIVING: {0} %", de:"BEIM FAHREN: {0} %", es:"AL CONDUCIR: {0} %", it:"IN GUIDA: {0} %", br:"NA ESTRADA: {0} %", pt:"NA ESTRADA: {0} %", pl:"W JEŹDZIE: {0} %", ru:"НА ХОДУ: {0} %", ja:"走行時: {0} %" },
      "S'AMORCE PLUS TOT A FROID": { en:"LIGHTS OFF SOONER WHEN COLD", de:"SPRINGT KALT FRÜHER AN", es:"SE ACTIVA ANTES EN FRÍO", it:"SI INNESCA PRIMA A FREDDO", br:"ATIVA MAIS CEDO A FRIO", pt:"ATIVA MAIS CEDO A FRIO", pl:"ZAPALA SIĘ WCZEŚNIEJ NA ZIMNO", ru:"РАНЬШЕ ВЫХОДИТ НА РЕЖИМ НА ХОЛОДНУЮ", ja:"冷間時に早く活性化" },
      "S'AMORCE PLUS TARD : PLUS DE FUMEE AU DEPART A FROID": { en:"LIGHTS OFF LATER: MORE SMOKE ON A COLD START", de:"SPRINGT SPÄTER AN: MEHR RAUCH BEIM KALTSTART", es:"SE ACTIVA MÁS TARDE: MÁS HUMO AL ARRANCAR EN FRÍO", it:"SI INNESCA PIÙ TARDI: PIÙ FUMO ALLA PARTENZA A FREDDO", br:"ATIVA MAIS TARDE: MAIS FUMAÇA NA PARTIDA A FRIO", pt:"ATIVA MAIS TARDE: MAIS FUMO NO ARRANQUE A FRIO", pl:"ZAPALA SIĘ PÓŹNIEJ: WIĘCEJ DYMU PRZY ZIMNYM STARCIE", ru:"ПОЗЖЕ ВЫХОДИТ НА РЕЖИМ: БОЛЬШЕ ДЫМА ПРИ ХОЛОДНОМ ПУСКЕ", ja:"活性化が遅い: 冷間始動で煙が増えます" },
      "MOINS DE SUIE DANS L'ADMISSION": { en:"LESS SOOT IN THE INTAKE", de:"WENIGER RUSS IM ANSAUGTRAKT", es:"MENOS HOLLÍN EN LA ADMISIÓN", it:"MENO FULIGGINE NELL'ASPIRAZIONE", br:"MENOS FULIGEM NA ADMISSÃO", pt:"MENOS FULIGEM NA ADMISSÃO", pl:"MNIEJ SADZY W DOLOCIE", ru:"МЕНЬШЕ САЖИ ВО ВПУСКЕ", ja:"吸気側のすすが減ります" },
      "LE SON RESTE CELUI DE SERIE": { en:"THE SOUND STAYS STOCK", de:"DER KLANG BLEIBT SERIENMÄSSIG", es:"EL SONIDO SIGUE SIENDO EL DE SERIE", it:"IL SUONO RESTA QUELLO DI SERIE", br:"O SOM CONTINUA O ORIGINAL", pt:"O SOM CONTINUA O DE SÉRIE", pl:"DŹWIĘK POZOSTAJE SERYJNY", ru:"ЗВУК ОСТАЁТСЯ СЕРИЙНЫМ", ja:"音は純正のままです" },
      "POP AND BANG {0} - FLAMME UNIQUE {1} - ANTILAG {2} : ILS SE REGLENT A LA CARTOGRAPHIE, UNE FOIS LE MOTEUR MONTE.": { en:"POP AND BANG {0} - SINGLE FLAME {1} - ANTILAG {2}: THEY ARE SET IN THE ENGINE MAP, ONCE THE ENGINE IS FITTED.", de:"POP AND BANG {0} - EINZELFLAMME {1} - ANTILAG {2}: SIE WERDEN IM KENNFELD EINGESTELLT, SOBALD DER MOTOR EINGEBAUT IST.", es:"POP AND BANG {0} - LLAMA ÚNICA {1} - ANTILAG {2}: SE AJUSTAN EN LA CARTOGRAFÍA, UNA VEZ MONTADO EL MOTOR.", it:"POP AND BANG {0} - FIAMMATA UNICA {1} - ANTILAG {2}: SI REGOLANO NELLA MAPPATURA, A MOTORE MONTATO.", br:"POP AND BANG {0} - CHAMA ÚNICA {1} - ANTILAG {2}: SÃO AJUSTADOS NO MAPEAMENTO, COM O MOTOR MONTADO.", pt:"POP AND BANG {0} - CHAMA ÚNICA {1} - ANTILAG {2}: AJUSTAM-SE NO MAPEAMENTO, COM O MOTOR MONTADO.", pl:"POP AND BANG {0} - POJEDYNCZY PŁOMIEŃ {1} - ANTILAG {2}: USTAWIA SIĘ JE W MAPIE SILNIKA PO ZAMONTOWANIU SILNIKA.", ru:"POP AND BANG {0} - ОДИНОЧНЫЙ ВЫСТРЕЛ {1} - АНТИЛАГ {2}: ОНИ НАСТРАИВАЮТСЯ В ПРОШИВКЕ ПОСЛЕ УСТАНОВКИ ДВИГАТЕЛЯ.", ja:"ポップアンドバン {0} - 単発アフターファイア {1} - アンチラグ {2}: エンジン搭載後に「ECUマップ」で設定します。" },
      "POP AND BANG {0} - FLAMME UNIQUE {1} : ILS SE REGLENT A LA CARTOGRAPHIE, UNE FOIS LE MOTEUR MONTE.": { en:"POP AND BANG {0} - SINGLE FLAME {1}: THEY ARE SET IN THE ENGINE MAP, ONCE THE ENGINE IS FITTED.", de:"POP AND BANG {0} - EINZELFLAMME {1}: SIE WERDEN IM KENNFELD EINGESTELLT, SOBALD DER MOTOR EINGEBAUT IST.", es:"POP AND BANG {0} - LLAMA ÚNICA {1}: SE AJUSTAN EN LA CARTOGRAFÍA, UNA VEZ MONTADO EL MOTOR.", it:"POP AND BANG {0} - FIAMMATA UNICA {1}: SI REGOLANO NELLA MAPPATURA, A MOTORE MONTATO.", br:"POP AND BANG {0} - CHAMA ÚNICA {1}: SÃO AJUSTADOS NO MAPEAMENTO, COM O MOTOR MONTADO.", pt:"POP AND BANG {0} - CHAMA ÚNICA {1}: AJUSTAM-SE NO MAPEAMENTO, COM O MOTOR MONTADO.", pl:"POP AND BANG {0} - POJEDYNCZY PŁOMIEŃ {1}: USTAWIA SIĘ JE W MAPIE SILNIKA PO ZAMONTOWANIU SILNIKA.", ru:"POP AND BANG {0} - ОДИНОЧНЫЙ ВЫСТРЕЛ {1}: ОНИ НАСТРАИВАЮТСЯ В ПРОШИВКЕ ПОСЛЕ УСТАНОВКИ ДВИГАТЕЛЯ.", ja:"ポップアンドバン {0} - 単発アフターファイア {1}: エンジン搭載後に「ECUマップ」で設定します。" },
      "ANTILAG {0} - HARD CUT {1} : ILS SE REGLENT A LA CARTOGRAPHIE, UNE FOIS LE MOTEUR MONTE.": { en:"ANTILAG {0} - HARD CUT {1}: THEY ARE SET IN THE ENGINE MAP, ONCE THE ENGINE IS FITTED.", de:"ANTILAG {0} - HARD CUT {1}: SIE WERDEN IM KENNFELD EINGESTELLT, SOBALD DER MOTOR EINGEBAUT IST.", es:"ANTILAG {0} - HARD CUT {1}: SE AJUSTAN EN LA CARTOGRAFÍA, UNA VEZ MONTADO EL MOTOR.", it:"ANTILAG {0} - HARD CUT {1}: SI REGOLANO NELLA MAPPATURA, A MOTORE MONTATO.", br:"ANTILAG {0} - HARD CUT {1}: SÃO AJUSTADOS NO MAPEAMENTO, COM O MOTOR MONTADO.", pt:"ANTILAG {0} - HARD CUT {1}: AJUSTAM-SE NO MAPEAMENTO, COM O MOTOR MONTADO.", pl:"ANTILAG {0} - HARD CUT {1}: USTAWIA SIĘ JE W MAPIE SILNIKA PO ZAMONTOWANIU SILNIKA.", ru:"АНТИЛАГ {0} - HARD CUT {1}: ОНИ НАСТРАИВАЮТСЯ В ПРОШИВКЕ ПОСЛЕ УСТАНОВКИ ДВИГАТЕЛЯ.", ja:"アンチラグ {0} - ハードカット {1}: エンジン搭載後に「ECUマップ」で設定します。" },
      "HARD CUT {0} : IL SE REGLE A LA CARTOGRAPHIE, UNE FOIS LE MOTEUR MONTE.": { en:"HARD CUT {0}: IT IS SET IN THE ENGINE MAP, ONCE THE ENGINE IS FITTED.", de:"HARD CUT {0}: ER WIRD IM KENNFELD EINGESTELLT, SOBALD DER MOTOR EINGEBAUT IST.", es:"HARD CUT {0}: SE AJUSTA EN LA CARTOGRAFÍA, UNA VEZ MONTADO EL MOTOR.", it:"HARD CUT {0}: SI REGOLA NELLA MAPPATURA, A MOTORE MONTATO.", br:"HARD CUT {0}: É AJUSTADO NO MAPEAMENTO, COM O MOTOR MONTADO.", pt:"HARD CUT {0}: AJUSTA-SE NO MAPEAMENTO, COM O MOTOR MONTADO.", pl:"HARD CUT {0}: USTAWIA SIĘ GO W MAPIE SILNIKA PO ZAMONTOWANIU SILNIKA.", ru:"HARD CUT {0}: НАСТРАИВАЕТСЯ В ПРОШИВКЕ ПОСЛЕ УСТАНОВКИ ДВИГАТЕЛЯ.", ja:"ハードカット {0}: エンジン搭載後に「ECUマップ」で設定します。" },
