  /* ===== V1.2.2 (CAPOT 3D) : LE BOUTON DU CAPOT ET LE BADGE DU MOTEUR REDUIT (plan-capot.md 8.6) =====
     Le meme bouton au garage, chez le concessionnaire et au 7e volet VOITURE 3D : OUVRIR LE CAPOT / FERMER LE CAPOT pour tout ce qui
     s'ouvre (capot, couvercle, trappe, cabine, panneaux, pont : un seul mot pour le joueur), VOIR LE MOTEUR / CACHER LE MOTEUR la ou le
     moteur se voit deja (moto, quad, kart...). Le badge dit qu'un moteur trop gros pour sa caisse y est montre reduit (un badge d'etat,
     jamais un mot sur la 3D). CAPOT : le mot du jeu (VUE CAPOT) ; le portugais du Portugal garde « capot ». */
  (function(){
    var A = {
      "OUVRIR LE CAPOT": { en:"OPEN THE BONNET", de:"HAUBE ÖFFNEN", es:"ABRIR EL CAPÓ", it:"APRI IL COFANO", br:"ABRIR O CAPÔ", pt:"ABRIR O CAPOT", pl:"OTWÓRZ MASKĘ", ru:"ОТКРЫТЬ КАПОТ", ja:"ボンネットを開ける" },
      "FERMER LE CAPOT": { en:"CLOSE THE BONNET", de:"HAUBE SCHLIESSEN", es:"CERRAR EL CAPÓ", it:"CHIUDI IL COFANO", br:"FECHAR O CAPÔ", pt:"FECHAR O CAPOT", pl:"ZAMKNIJ MASKĘ", ru:"ЗАКРЫТЬ КАПОТ", ja:"ボンネットを閉じる" },
      "VOIR LE MOTEUR": { en:"SHOW THE ENGINE", de:"MOTOR ZEIGEN", es:"VER EL MOTOR", it:"MOSTRA IL MOTORE", br:"VER O MOTOR", pt:"VER O MOTOR", pl:"POKAŻ SILNIK", ru:"ПОКАЗАТЬ ДВИГАТЕЛЬ", ja:"エンジンを見る" },
      "CACHER LE MOTEUR": { en:"HIDE THE ENGINE", de:"MOTOR AUSBLENDEN", es:"OCULTAR EL MOTOR", it:"NASCONDI IL MOTORE", br:"OCULTAR O MOTOR", pt:"OCULTAR O MOTOR", pl:"UKRYJ SILNIK", ru:"СКРЫТЬ ДВИГАТЕЛЬ", ja:"エンジンを隠す" },
      "MOTEUR REDUIT A {0} %": { en:"ENGINE SHOWN AT {0} %", de:"MOTOR AUF {0} % VERKLEINERT", es:"MOTOR REDUCIDO AL {0} %", it:"MOTORE RIDOTTO AL {0} %", br:"MOTOR REDUZIDO A {0} %", pt:"MOTOR REDUZIDO A {0} %", pl:"SILNIK POMNIEJSZONY DO {0} %", ru:"ДВИГАТЕЛЬ УМЕНЬШЕН ДО {0} %", ja:"エンジン縮小表示 {0} %" }
    };
    for (var k in A) for (var l in A[k]) if (I18N[l]) I18N[l][k] = A[k][l];
  })();
