        for (var p = el.parentElement; p && p !== document.body; p = p.parentElement){
          var oy = getComputedStyle(p).overflowY;
          if ((oy === 'auto' || oy === 'scroll') && p.scrollHeight > p.clientHeight + 1) return p;
        }
        return null;
