        var el = document.activeElement, h = hauteurClavier();
        if (!champ(el) || h < 80){ fermer(); return; }     // moins de 80 px : pas de clavier (barre d'outils seule, ou rien)
        ouvert = true;
        document.documentElement.style.setProperty('--clavier-h', h + 'px');
        document.documentElement.classList.add('clavier');
        /* le panneau vient de remonter : on mesure a l'image suivante */
