      var mini = Math.max(10, base * 0.8), fs = base;
      if (swB > cw - 4) fs = Math.max(mini, Math.floor(base * (cw - 4) / swB * 4) / 4);
      if (fs !== fsCur) sb.style.fontSize = (fs >= base) ? '' : fs + 'px';
