    if (state.rupteurActif && r >= rupteurCoupure()) thr = 0;     // le limiteur coupe ; V1.1.0.61 : celui de la carte (la fiche a l'origine)
    if (coupeActive()) thr = 0;                                 // V1.1.0.6 : le coupe-contact aussi
    var tF = engineBrakeTorque(v, r);
    return -tF + thr * (coupleEffectif(v, r) * boostMultiplier(v) * multAirMoteur(v, r) * overRevTorqueMult(r) + tF);
