    if (g < 1 || n < 2) return g;
    /* V1.1.0.34 : AU BANC, UNE MESURE SE FAIT SUR UN SEUL RAPPORT - ni montee au rupteur, ni carte, ni kickdown : le passage
       s'acheve au rupteur dans bancEssaiTick. Au-dessus de 7 km/h seulement : un rouleau freine jusqu'a l'arret garde le
       retour en premiere. */
    if (state.speed > 7 && surRouleaux() && bancEssai.phase === 'mesure' && g === bancEssai.rapport) return g;
    /* V1.0.89.360 : le selecteur d'une automatique ancienne sur 2 ou 1 - la boite ne monte plus au-dela, et descend des que le regime le permet. */
    var nLim = n;
