    function I(a){ return a[rg.i] + (a[rg.i + 1] - a[rg.i]) * rg.t; }
    var deb0 = I(O.deb), calO = I(O.avF), airRel = cartoAirRel(v, O, p, pO, env.air), lim = K.fumee * deb0 * airRel;
