    var cle = O.cle + '|' + JSON.stringify(cartoObjet(cartoNormaliser(c) || cartoNeutre(f), false)) + '|' + env.cle + '|' + L.roue + '/' + L.pieces
              + '/' + L.injCap + '|' + (v.rupteurActif === false ? 0 : 1) + '|' + LANG + '|' + U.sym('temp') + '|' + U.sym('pression');     // les textes sont mis en forme
