      if (q.egt >= P.degat){ niv('rouge'); probs.push([1, 'egt', i, ["{0} TR : EGT {1} - ALERTE {2}", Math.round(tr), U.txt('temp', q.egt), U.txt('temp', P.alerte)], q.egt]); }
      else if (q.egt >= P.alerte){ niv('orange'); probs.push([4, 'egt', i, ["{0} TR : EGT {1} - ALERTE {2}", Math.round(tr), U.txt('temp', q.egt), U.txt('temp', P.alerte)], q.egt]); }
      if (O.sural){
        if (q.p > mPr.bar){ mPr.bar = q.p; mPr.i = i; }
        if (L.pieces > 0 && q.p >= L.pieces){ niv('rouge'); probs.push([2, 'pression', i, ["{0} TR : LA PRESSION DEPASSE CE QUE TIENNENT LES PIECES", Math.round(tr)], q.p]); }
        else if (L.roue > 0 && q.p >= L.roue - 0.05){ niv('orange'); probs.push([4, 'pression', i, ["{0} TR : LA PRESSION DEPASSE LA ROUE DU TURBO", Math.round(tr)], q.p]); }
      }
