    if (!g) return;
    var W = etat.w, H = etat.h, O = cartoOrigine(v), A = cartoAxe(v), E = cartoOuvrir(v), res = cartoEstOuvert(v);
    if (!O || !E || !res) return;
    var tb = prepVue.cartoTable, l = cartoLigneCourante(), sel = cartoPointCourant(), L = cartoLimites(v), i;
    var s = cartoEdSerie(v, E, res, tb, l), ech = (U0.drag && U0.drag.ech) ? U0.drag.ech : cartoEdEchelle(v, tb, s);
    var f = 10.5, dec = ech.pas >= 1 ? 0 : (ech.pas >= 0.1 ? 1 : 2);
    function lab(y){
      if (tb === 'pr') return U.num('pression', y, U.sym('pression') === 'BAR' ? dec : 0);
      return (+y).toFixed(dec);
    }
    neoPolice(g, f, 500);
    if ('letterSpacing' in g) g.letterSpacing = '0px';
    var labs = [], y;
    for (y = ech.lo; y <= ech.hi + ech.pas * 0.01; y += ech.pas) labs.push(y);
    var mg = 8;
    labs.forEach(function(q){ mg = Math.max(mg, g.measureText(lab(q)).width); });
    var x0 = Math.ceil(mg) + 8, x1 = W - 8, y0 = 8, y1 = H - 20;
    var ta = A.tr[0], tz = A.tr[7], xa = ta - (tz - ta) * 0.04, xb = tz + (tz - ta) * 0.06;
    function X(tr){ return x0 + (x1 - x0) * (tr - xa) / (xb - xa); }
    function Y(q){ return y1 - (y1 - y0) * (q - ech.lo) / (ech.hi - ech.lo); }
