    for (var r = Math.ceil(xa / pX) * pX; r <= xb; r += pX) gr.push(r);
    gr.forEach(function(r2){ var xx = Math.round(X(r2)) + 0.5; g.moveTo(xx, y0); g.lineTo(xx, y1); });
    g.stroke();
    g.strokeStyle = NEO.bord; g.beginPath(); g.moveTo(x0, Math.round(y1) + 0.5); g.lineTo(x1, Math.round(y1) + 0.5); g.stroke();
    g.textBaseline = 'middle'; g.textAlign = 'right'; g.fillStyle = NEO.gris;
    labs.forEach(function(q){ g.fillText(lab(q), x0 - 5, Y(q)); });
    g.textAlign = 'center';
    gr.forEach(function(r2, k){ g.fillText(String(Math.round(r2)) + (k === gr.length - 1 ? ' ' + t("TR") : ''), Math.min(X(r2), x1 - 14), y1 + 11); });
    g.save(); g.beginPath(); g.rect(x0, y0, x1 - x0, y1 - y0); g.clip();
    /* ce qu'il ne faut pas franchir */
    neoPolice(g, 10, 600); g.textBaseline = 'top';
    if (s.lim){
      g.beginPath(); g.moveTo(x0, y0); g.lineTo(x0, Y(s.lim[0]));
      for (i = 0; i < 8; i++) g.lineTo(X(A.tr[i]), Y(s.lim[i]));
      g.lineTo(x1, Y(s.lim[7])); g.lineTo(x1, y0); g.closePath();
      g.fillStyle = 'rgba(255,59,48,0.14)'; g.fill();
      g.beginPath(); g.moveTo(x0, Y(s.lim[0])); for (i = 0; i < 8; i++) g.lineTo(X(A.tr[i]), Y(s.lim[i])); g.lineTo(x1, Y(s.lim[7]));
      g.strokeStyle = '#ff5a4f'; g.lineWidth = 1.6; g.stroke();
      g.textAlign = 'left'; g.fillStyle = '#ff5a4f'; g.fillText(t("CLIQUETIS") + ' (' + cartoCarbuTexte(v) + ')', x0 + 6, y0 + 4);
    }
    if (s.fum){
      g.beginPath(); g.moveTo(x0, y0); g.lineTo(x0, Y(s.fum[0]));
      for (i = 0; i < 8; i++) g.lineTo(X(A.tr[i]), Y(s.fum[i]));
      g.lineTo(x1, Y(s.fum[7])); g.lineTo(x1, y0); g.closePath();
      g.fillStyle = 'rgba(152,162,160,0.13)'; g.fill();
      g.beginPath(); g.moveTo(x0, Y(s.fum[0])); for (i = 0; i < 8; i++) g.lineTo(X(A.tr[i]), Y(s.fum[i])); g.lineTo(x1, Y(s.fum[7]));
      g.setLineDash([5, 4]); g.strokeStyle = '#98a2a0'; g.lineWidth = 1.4; g.stroke(); g.setLineDash([]);
      g.textAlign = 'left'; g.fillStyle = '#98a2a0'; g.fillText(t("FUMEE NOIRE"), x0 + 6, y0 + 4);
    }
    if (tb === 'ri' && !O.diesel){
      [[0.95, 9, 'rgba(255,59,48,0.10)', '#ff5a4f', "TROP PAUVRE"], [0.80, 0.90, 'rgba(57,255,106,0.07)', NEO.accent, "PUISSANCE"],
       [-9, 0.78, 'rgba(152,162,160,0.10)', '#98a2a0', "RICHE", 1]].forEach(function(b){
        var ya = Y(Math.min(b[1], ech.hi)), yb = Y(Math.max(b[0], ech.lo));
        if (yb - ya < 4) return;
        g.fillStyle = b[2]; g.fillRect(x0, ya, x1 - x0, yb - ya);
        g.fillStyle = b[3]; g.textAlign = b[5] ? 'left' : 'right'; g.textBaseline = b[5] ? 'bottom' : 'top';
        g.fillText(t(b[4]), b[5] ? x0 + 6 : x1 - 4, b[5] ? yb - 3 : ya + 3);     // RICHE en bas a gauche : la courbe y est haute
      });
    }
    if (tb === 'pr' && L.roue > 0){
      var yP = Y(L.pieces), yR = Y(L.roue), serre = Math.abs(yR - yP) < 13;
      g.strokeStyle = '#ff5a4f'; g.lineWidth = 1.6; g.beginPath(); g.moveTo(x0, Math.round(yP) + 0.5); g.lineTo(x1, Math.round(yP) + 0.5); g.stroke();
      g.setLineDash([4, 4]); g.strokeStyle = NEO.ambre; g.lineWidth = 1.4; g.beginPath(); g.moveTo(x0, Math.round(yR) + 0.5); g.lineTo(x1, Math.round(yR) + 0.5); g.stroke(); g.setLineDash([]);
      /* les libelles a gauche : la pression n'y est pas encore montee */
      g.textAlign = 'left'; g.textBaseline = 'bottom'; g.fillStyle = '#ff5a4f'; g.fillText(t("PIECES"), x0 + 6, yP - 2);
      g.fillStyle = NEO.ambre;
      if (serre){ g.textBaseline = 'top'; g.fillText(t("ROUE DU TURBO"), x0 + 6, yR + 2); } else g.fillText(t("ROUE DU TURBO"), x0 + 6, yR - 2);
    }
