    g.setLineDash([5, 4]); g.strokeStyle = 'rgba(233,237,236,0.45)'; g.lineWidth = 1.5; g.stroke(); g.setLineDash([]);
    g.beginPath(); for (i = 0; i < 8; i++){ if (i) g.lineTo(X(A.tr[i]), Y(s.vals[i])); else g.moveTo(X(A.tr[i]), Y(s.vals[i])); }
