    neoPolice(g, 12.5, 700);
    var tx = cartoFmt(v, tb, s.vals[sel]), tw = g.measureText(tx).width + 14, bh = 20;
    var bx = Math.max(x0 + 2, Math.min(x1 - tw - 2, xs - tw / 2)), by = ys - 20 - bh;
