  var VT_P = { x: 0, y: 0, h: 0, k: 0 }, VT_J = { x: 0, y: 0, h: 0, v: 0, s: 0, lon: 4.5, joueur: true, hz: 0 }, VT_M = { s: 0, lat: 0, h: 0 };
  var VT_PX = new Float64Array(40), VT_PY = new Float64Array(40), VT_PH = new Float64Array(40), VT_AXE = new Float64Array(900);
  var VT_CHOCS = [], VT_VIDE = [], VT_AXC = new Float64Array(60);     // V1.0.89.338 : l'axe pres du joueur, pour le choc
