      if (t.type !== 'rue' || t.sens < 0) continue;
      var pe = G.rues[t.rue].pea;
      if (!pe) continue;
      var zBar = t.s0 + pe.u, cle = pe.cle + '@' + Math.round(t.s0);
      if (fr > zBar + 30){ if (c.pea && c.pea.cle === pe.cle) c.pea = null; continue; }
      if (c.peaFait === cle){ if (c.pea) c.pea.ph = (fr > zBar + 3) ? 3 : 2; return Infinity; }
      var d = zBar - PEAGE.arretPnj - fr;
