    var loin = Math.abs(p.lateral || 0) > GT_LIBRE.ancreLoin;
    if (L.tArriere < 1 && !loin && !L.malPose) return;
    /* Loin de tout (un coin de la carte a 1 km des routes), la rue la plus proche ne change pas d'un tick a l'autre : on ne refait
       l'ancre qu'une fois toutes les deux secondes, et seulement si une rue est vraiment plus proche que l'ancre (50 m). */
    if (L.tArriere < 1 && L.t - (L.tAncre || -9) < 2) return;
