    if (c === 'huile2t') return v.temps === '2T' && v.arch !== 'R' && v.carburant !== 'diesel' && !estOP(v);
    if (PRODUITS_GARAGE.indexOf(c) >= 0) return false;
    if (estVapeur(v)) return c === natif || c === 'kerosene' || c === 'gazole';     // V1.1.0.54 : un bruleur a liquide (provisoire)
