    var reg = Math.max(0, Math.min(1, ((state.rpm || 0) - (state.idle || 0)) / Math.max(1, (state.rupteur || 6000) - (state.idle || 0))));
    var dur = 0.35 + 0.45 * cmd + 0.20 * reg, dMax = 0;          // un moteur qui travaille souffre davantage
