          var z = Math.round(zMin + (zMax - zMin) * (0.2 + 0.6 * villHach(k + 0.61 + e * 0.173)));
          if (!rondLibre(z)) continue;
          var i1 = Math.floor(villHach(k + 0.83) * nm.length) % nm.length;
          var i2 = (i1 + 1 + Math.floor(villHach(k + 0.91) * (nm.length - 1))) % nm.length;
          if (nm[i1] === b.nom) i1 = (i1 + 1) % nm.length;                     // jamais le nom du tout-droit sur une sortie
          while (nm[i2] === b.nom || i2 === i1) i2 = (i2 + 1) % nm.length;
