    btA(P, sB, latB, 9, 4.2, 16, 0, 0, 0.90, 0.88, 0.82);                    // la boutique
    btA(P, sB, latB, 10.6, 0.45, 17.6, 4.2, 0, 0.30, 0.31, 0.33);            // son toit
    btA(P, sB, latB - 4.53, 0.06, 2.4, 11, 0.3, 0, 0.13, 0.19, 0.26);        // la vitrine
    btA(P, sB + 6.2, latB - 4.54, 0.06, 2.2, 1.4, 0, 0, 0.35, 0.36, 0.38);   // la porte
    luA(P, sB, latB - 4.75, 0.2, 0.7, 13, 3.35, 0, 0.74, 0.12, 0.12);        // l'enseigne
