    var e = W / (2 * portee), cx = W / 2, cy = H * 0.74, lat = p.lateral || 0, pas = 6, av = [[0, 0, 0]], ar = [[0, 0, 0]], x = 0, y = 0, th = 0, s, k, i;
    for (s = sJ; s < sJ + 900; s += pas){ k = courbureMonde(s + pas / 2); th += k * pas / 2; x += Math.sin(th) * pas; y += Math.cos(th) * pas; th += k * pas / 2; av.push([x, y, th]); }
    x = 0; y = 0; th = 0;
    for (s = sJ; s > sJ - 260; s -= pas){ k = courbureMonde(s - pas / 2); th -= k * pas / 2; x -= Math.sin(th) * pas; y -= Math.cos(th) * pas; th -= k * pas / 2; ar.push([x, y, th]); }
