      actif: true,
      vitre: vitreHab.ouv, vitreBouge: vitreHab.ouv !== vitreHab.cible,     // V1.2.5 (VITRE OUVERTE)
      hab: habDesc(v), aigR: aigH[0], aigV: aigH[1],     // V1.2.5 (HABITACLE 3D) : l'habitacle en metres, ses aiguilles
      cle: cle3dDe(v),     // V1.0.89.389 : la silhouette dessinee d'un modele, sinon celle de sa categorie
      annee: anneeFiche(v),     // V1.2.5 (VEHICULES V2) : la forme de la caisse suit l'annee
      coul: couleurVehicule(v),
