    var advVu = c.vu3d;
    var tVu = route.tVu || 0;
    var d = ecartPiste(c.s + (c.v || 0) * tVu, z);     // V1.0.89.429 : sur le tour, pas sur une droite
    if (d < -16 || d > VUE_3D) return null;     // V1.0.89.404 : un peu plus large derriere - la camera de suivi recule de sept metres
    var pas = Math.max(0, Math.min(0.25, dt || 0));
    var rR = Math.max(0.12, tireRadius(veh.pneuTailleAvant || "205/55R16"));
