      var vitA = (veh.vitesses && veh.vitesses.length) ? Math.max.apply(null, veh.vitesses) : 100;
      var vDirA = Math.max(40, (veh.vitesses && veh.vitesses.length === 1) ? veh.vitesses[0] : vitA * 0.5);
