      degats: duelDegatsVus(c),
      annee: (typeof anneeFiche === 'function') ? anneeFiche(veh) : 0,     // V1.2.5 (VEHICULES V2, L3) : l'adversaire du duel a la forme de son annee
      cle: (typeof cle3dDe === 'function') ? cle3dDe(veh) : ((typeof categorieDe === 'function') ? categorieDe(veh) : 'berline'),     // V1.2.2 (verification d'ensemble) : la silhouette dessinee (2CH, TORENO 86), comme le joueur
      coul: duelCouleurAdv(veh),
      sorties: (veh.sorties === 2) ? 2 : 1,
      arch: archVu(veh), cyl: cylVu(veh),
      aileronAv: aileVue(veh, 'av'), aileronAr: aileVue(veh, 'ar'),     // V1.0.89.453
      roue: advVu.roue, braquage: advVu.braquage,
      lacet: advVu.lacet || 0,
      lon: c.lon || 4.4, larg: c.larg || 1.8, haut: c.haut || 1.45,     // V1.2.5 (DEGATS V2, RELECTURE) : ses cotes (les eclats et la roue du duel partent de sa caisse)     // V1.1.0.66 : voir L'ADVERSAIRE REGARDE OU IL VA
      roulis: 0, cabrage: 0,
      frein: !!c.freine,
      recul: false,
      phares: !!(meteo && meteo.nuit) || !!tunnelA(c.s),
      cligno: 0,
      remorque: remorque3d(veh),
      helice: rotA, heliceAng: rotA ? advVu.hel.a : 0, heliceTr: rotA ? advVu.hel.tr : 0     // V1.1.0.9
