  NIVEAUX_QUALITE.tres_faible.fumeeOrbite = false; NIVEAUX_QUALITE.faible.fumeeOrbite = true; NIVEAUX_QUALITE.moyen.fumeeOrbite = true;
  NIVEAUX_QUALITE.eleve.fumeeOrbite = true; NIVEAUX_QUALITE.ultra.fumeeOrbite = true;
