    try{ mem = +navigator.deviceMemory || 0; }catch(e){}
    try{
      if (localStorage.getItem('simulmoteur_son_leger_appareil_v1') === '1') leger = true;
      var so = JSON.parse(localStorage.getItem('simulmoteur_son_sonde_v1') || 'null');
      if (so && so.leger) leger = true;
    }catch(e){}
