          if (coupe.vapCompte >= 1){ coupe.vapCompte = Math.min(1, coupe.vapCompte - 1); if (coupe.vapBouf.length < 14) coupe.vapBouf.push({ age: 0, f: 0.4 + 0.6 * flux }); }
