    var v = state.vehicle, T = TEINTES_COUPE, LC = coupe.L || bancCadre(ctx, W, H);
    var r = g.manivelle, L = g.bielle, al = g.alesage, psi = coupe.psi || 0;
    var DG = degatsCoupe(), cDeg = null;
    if (DG) g.cylindres.forEach(function(c){ if (!cDeg || c.prof > cDeg.prof) cDeg = c; });
    var simple = g.vapEffet === 'simple', uni = g.vapDistrib === 'uniflow', pisT = g.vapDistrib === 'tiroir_cyl';
    var ch = state.chaud || {}, nom = Math.max(2, v.chaudBar || 20), pres = Math.max(0, Math.min(1.2, (ch.bar || 0) / nom));
