    var dG0 = Math.max(r * 1.30, L - r - xh - al * 0.08), dG1 = L + r + xh + al * 0.056;
    var dBas = Math.max(r * 1.15, dG0 - al * 0.06);
    var dCB0 = dG1, dCB1 = dCB0 + al * 0.16;
    var rodOff = dCB1 + jeu + lp / 2 - (L - r);
