    var eB1 = wCyl + al * 0.46;                          // la boite a vapeur, cote s
    var dPB = dCB1 + al * 0.07, dPT = dCyl1 - al * 0.07;  // les lumieres, pres de chaque fond
    var dMid = (dCB1 + dCyl1) / 2;
