    var bx0 = maxX + al * 0.55, bx1 = bx0 + bw, by1 = maxY - r * 0.15 - (cond ? hM * 0.30 : 0), by0 = by1 - bh;
    var chx = (bx0 + bx1) / 2, chw = al * 0.30, chTop = Math.min(minY - al * 0.35, by0 - al * 1.2);
    borner([bx1 + al * 0.25, by1]); borner([bx0 - al * 0.1, by0]);
