      ps.sort(function(a, b){ return (a[0] - b[0]) || (a[1] - b[1]); });
      function tour(o, a, b){ return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]); }
      var dessous = [], dessus = [];
