      for (i = ps.length - 1; i >= 0; i--){ while (dessus.length >= 2 && tour(dessus[dessus.length - 2], dessus[dessus.length - 1], ps[i]) <= 0) dessus.pop(); dessus.push(ps[i]); }
      var h = dessous.slice(0, -1).concat(dessus.slice(0, -1));
