        [dPB, dPT].forEach(function(dp){ trace(rect(dp - al * 0.04, dp + al * 0.04, s * wAle, s * e0).map(function(q){ return Pt(q[0], q[1]); }), true); ctx.fill(); });
        // la vapeur vive dans la boite
        trace(rect(dCB1 + al * 0.03, dCyl1 - al * 0.03, s * e1, s * (eB1 - al * 0.06)).map(function(q){ return Pt(q[0], q[1]); }), true);
        ctx.globalAlpha = (0.18 + 0.55 * Math.min(1, pres)) * (0.30 + 0.70 * prof); ctx.fillStyle = T.gaz[2]; ctx.fill(); ctx.globalAlpha = 1;
        if (pisT){
          // piston-tiroir : deux disques sur une tige
          ctx.strokeStyle = tc(T.alu); ctx.lineWidth = Math.max(1, al * 0.035 * ech); segment(Pt(xT - lT / 2, s * (e0 + al * 0.08)), Pt(xT + lT / 2, s * (e0 + al * 0.08))); ctx.lineWidth = lg;
          ctx.fillStyle = tc('#b08040');
          [-1, 1].forEach(function(sg){ trace(rect(xT + sg * lT / 2 - al * 0.05, xT + sg * lT / 2 + al * 0.05, s * e0, s * e1).map(function(q){ return Pt(q[0], q[1]); }), true); ctx.fill(); ctx.strokeStyle = tc(T.arete); ctx.stroke(); });
        } else {
          // tiroir en D : un bloc de bronze, creuse cote glace
          trace([[xT - lT / 2, e0], [xT + lT / 2, e0], [xT + lT / 2, e1], [xT - lT / 2, e1]].map(function(q){ return Pt(q[0], s * q[1]); }), true);
          ctx.fillStyle = tc('#b08040'); ctx.fill(); ctx.strokeStyle = tc(T.arete); ctx.stroke();
          trace([[xT - lT * 0.28, e0], [xT + lT * 0.28, e0], [xT + lT * 0.20, e0 + al * 0.09], [xT - lT * 0.20, e0 + al * 0.09]].map(function(q){ return Pt(q[0], s * q[1]); }), true);
          ctx.fillStyle = tc(T.creux); ctx.fill();
        }
        // la tige du tiroir et, sur le cylindre de devant, la barre d'excentrique jusqu'au vilebrequin
        ctx.strokeStyle = tc(T.alu); ctx.lineWidth = Math.max(1, al * 0.03 * ech);
        segment(Pt(xT - lT / 2, s * (e0 + e1) / 2), Pt(dCB0 - al * 0.05, s * (e0 + e1) / 2));
