          var bout = Pt(dCB0 - al * 0.05, s * (e0 + e1) / 2);
          ctx.strokeStyle = tc(T.acier); ctx.lineWidth = Math.max(1, al * 0.045 * ech); segment(ex, bout);
          var ee = PX(ex); ctx.beginPath(); ctx.arc(ee[0], ee[1], Math.max(1.5, r * 0.22 * ech), 0, Math.PI * 2); ctx.strokeStyle = tc(T.alu); ctx.lineWidth = Math.max(1, lg); ctx.stroke();
