      trace([Pk(dBas, -wBati), Pk(dCB0, -wBati), Pk(dCB0, -wCouv), Pk(dCB1, -wCouv), Pk(dCB1, -wCyl), Pk(dCyl1, -wCyl), Pk(dCyl1, -wCouv), Pk(dCT1, -wCouv),
             Pk(dCT1, wCouv), Pk(dCyl1, wCouv), Pk(dCyl1, wCyl), Pk(dCB1, wCyl), Pk(dCB1, wCouv), Pk(dCB0, wCouv), Pk(dCB0, wBati), Pk(dBas, wBati)], false);
      ctx.stroke();
      if (!uni){ trace([Pk(dCB1, s * wCyl), Pk(dCB1, s * eB1), Pk(dCyl1, s * eB1), Pk(dCyl1, s * wCyl)], false); ctx.stroke(); }
      ctx.strokeStyle = T.filet; ctx.lineWidth = lg;
