    ctx.lineWidth = lg;
    /* --- V1.1.0.57 : la PURGE - un jet sous chaque bout de cylindre de la rangee de devant, du cote oppose a la boite --- */
    if (etatPurge.niv > 0.02){
      rangInfo.forEach(function(R){
        var e = -R.s * wCyl;
        [dCyl1 - al * 0.06].concat(simple ? [] : [dCB1 + al * 0.06]).forEach(function(dd){
          var p0 = PX(pointRang(R.B, dd, e, R.kmax)), p1 = PX(pointRang(R.B, dd, e * 1.6, R.kmax));
          jetPurgeCoupe(ctx, p0[0], p0[1], p1[0] - p0[0], p1[1] - p0[1], al * 1.0 * ech, etatPurge.niv);
        });
      });
    }
    /* --- 5. la chaudiere, ses tuyaux, la cheminee (chaudiereCoupe) : la vapeur vive va a la boite de la rangee la plus proche --- */
    var R0 = null;
    rangInfo.forEach(function(R){
      var p = pointRang(R.B, dMid, uni ? 0 : R.s * eB1, R.kmax);
      if (!R0 || p[0] > R0.x + al * 0.05) { R0 = R; R0.x = p[0]; }
    });
    var k0 = R0 ? R0.kmax : 0;
    var arriveV = R0 ? (uni ? pointRang(R0.B, dCT1 + al * 0.22, 0, k0) : pointRang(R0.B, dCyl1 - al * 0.12, R0.s * eB1, k0)) : [bx0, by0];
    var sortieE = R0 ? (uni ? pointRang(R0.B, dMid, -R0.s * al * 0.82, k0) : pointRang(R0.B, dMid, R0.s * eB1, k0)) : [bx0, by1];
    var c0 = PX([bx0, by0]), c1 = PX([bx1, by1]);
    chaudiereCoupe(ctx, v, { x0: c0[0], x1: c1[0], y0: c0[1], y1: c1[1], yChem: PX([0, chTop])[1],
                             yCond0: PX([0, by1 + hM * 0.04])[1], yCond1: PX([0, by1 + hM * 0.28])[1] },
                   PX(arriveV), PX(sortieE), tourne, dt, lg, true);     // V1.1.0.57 : la purge est deja dessinee sous les cylindres
