    ctx.beginPath(); ctx.moveTo(bord[0][0], bord[0][1]);
    for (i = 1; i <= n; i++) ctx.lineTo(bord[i][0], bord[i][1]);
    ctx.lineTo(h0[0], h0[1]); ctx.lineTo(h1[0], h1[1]); ctx.closePath();
    ctx.fillStyle = TEINTES_COUPE.creux; ctx.fill();
    ctx.beginPath(); ctx.moveTo(bord[0][0], bord[0][1]);
    for (i = 1; i <= n; i++) ctx.lineTo(bord[i][0], bord[i][1]);
    ctx.strokeStyle = 'rgba(255,' + Math.round(140 + 80 * ch) + ',' + Math.round(40 + 60 * ch) + ',' + (0.60 + 0.35 * ch).toFixed(3) + ')';
    ctx.lineWidth = Math.max(1, lg * 1.3); ctx.stroke();
    if (ch > 0.02){
      var m = bord[Math.round(n * 0.6)], rG = Math.max(3, al * 0.30 * kf * ech);
      var gl = ctx.createRadialGradient(m[0], m[1], 0, m[0], m[1], rG);
      gl.addColorStop(0, 'rgba(255,210,120,' + (0.70 * ch).toFixed(3) + ')');
      gl.addColorStop(1, 'rgba(255,90,10,0)');
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = gl; ctx.fillRect(m[0] - rG, m[1] - rG, rG * 2, rG * 2);
    }
