        qs.forEach(function(x){ qm[0] += x.q[0] / qs.length; qm[1] += x.q[1] / qs.length; });
        poserBrides(Tb, t.volutes ? 2 : 1, [qm[0] - t0[0], qm[1] - t0[1]]);
        qs.forEach(function(x){
          var br = Tb.brides[t.volutes ? x.volute : 0];
          tube([x.q, br.e], 'ech', s * 0.095, 1, false, { colliers: true, pal: x.pal });
          br.J = [(x.q[0] + br.e[0]) / 2, (x.q[1] + br.e[1]) / 2];
          br.relie = true;     // V1.2.1 : cette bride a son tube (bridesReliee)
        });
