      var z = [pt(-0.15, -0.75), pt(0.30, -0.05), pt(-0.30, 0.05), pt(0.15, 0.75)];
      ctx.strokeStyle = '#9fdcff'; ctx.lineWidth = Math.max(1, h * 0.16); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
      ctx.beginPath(); ctx.moveTo(z[0][0], z[0][1]);
