    var dx = nx * Math.cos(ang) + ux * Math.sin(ang), dy = ny * Math.cos(ang) + uy * Math.sin(ang);
    ctx.strokeStyle = '#161b1c'; ctx.lineWidth = Math.max(1.2, R * 0.30); ctx.lineCap = 'round';
