      var pasV = w * 0.36, dec = (((ang / (Math.PI * 2)) % 1) + 1) % 1 * pasV;
      ctx.beginPath();
      for (var xv = -w - pasV; xv < w + pasV; xv += pasV){
        if (casseB && Math.round((xv + w) / pasV) % 3 === 1) continue;     // V1.1.0.25 : des filets arraches
        for (var sg = -1; sg <= 1; sg += 2){ var pa = Q(xv + dec, sg * h * 0.55), pb = Q(xv + dec + pasV * 0.55, sg * h * 0.02); ctx.moveTo(pa[0], pa[1]); ctx.lineTo(pb[0], pb[1]); }
      }
