        var kDose = sep2 ? (((state.huile && state.huile.niveau > 0.05) ? 1 : 0) + Math.max(0, h2 - 0.01) / 0.02) : Math.min(3, h2 / HUILE_2T_DOSE);
        var kType = (ty2 === 'moteur4t') ? 1.6 : (ty2 === '2t_synth' ? 0.55 : (ty2 === '2t_min' ? 1.25 : 1));
        if (graissage2T(v) === 'competition') kType *= 0.6;
        /* V1.1.0.62 : marquee 'd2t' avec sa dose - la route en garde le voile (FUMEE_K().d2tRoute), l'antipollution n'en lit que l'exces. */
