      var gr = ctx.createRadialGradient(0, 0, 0, 0, 0, rr);
      gr.addColorStop(0, 'rgba(' + c + ',' + al.toFixed(3) + ')');
      gr.addColorStop(0.5, 'rgba(' + c + ',' + (al * 0.5).toFixed(3) + ')');
      gr.addColorStop(1, 'rgba(' + c + ',0)');
      ctx.fillStyle = gr; ctx.fillRect(-rr, -rr, 2 * rr, 2 * rr);
