  /* Un moteur a combustion interne : celui qui peut avoir un joint de culasse. */
  function fumeeCombustion(v){ var f = fumeeFamille(v); return !!f && f !== 'T' && f !== 'VAP' && f !== 'ST'; }
  /* Le S neutre : rien ne sort, rien n'est retenu, la richesse est juste. */
  function fumeeVide(){
    var S = { v: null, t: 0, fam: '', tourne: false, coupure: false, gaz: 0, rpmR: 0, flux: 0, froid: 0, amb: 0, gel: 0,
              lambda: 1, lambdaFum: 1, rates: 0, kS: 0, passage: 1, kSortie: 0, suieMult: 1, forceCharge: 0, porteCharge: 0,
              suieBrute: 0, huileAnormale: 0, vapeur: 0, chaleur: 0, filet: 0, couches: [],     // V1.1.0.69 : filet
              gen: { suie: 0, huile: 0, blanc: 0, gris: 0 }, kGenre: { suie: 1, huile: 1, blanc: 1, gris: 1 }, pr: null };
    S.ajouter = function(a, T, genre){ if (a > 0.002 && T) S.couches.push([Math.min(0.95, a), T[0], T[1], T[2], genre || 'blanc']); };
    return S;
  }
  /* LE MODELE. Une couche : [opacite, R, G, B, genre(, marque, dose)]. Genres : suie (carbone qui n'est pas le noir propre du
     diesel - essence riche, injection directe, gazole sous une bougie, carte riche), suieD (le noir du diesel : la coupe ; la
     route l'emet par suieEnRoulant et filetDiesel), huile (bleu), blanc (liquide, eau, imbrule d'un diesel froid, regeneration),
     gris (friture, emballement), vap (la condensation : la coupe ; la route l'emet par vapeurFroid), base (le voile normal d'une
     essence : la coupe seulement), blancCoupe (les rates blancs d'un melange pauvre : la coupe seulement, comme avant). */
