    function cT(a, T, genre, marque){ if (a > 0.002) L.push(marque ? [Math.min(0.95, a), T[0], T[1], T[2], genre, marque] : [Math.min(0.95, a), T[0], T[1], T[2], genre]); }
    /* Ce qui brule : les parts du melange de la ligne (les produits du garage a part, voir couchesProduits). */
