  /* Le S du vehicule en main, recalcule au plus une fois par pas (le tick le force juste avant ses emetteurs). */
  function fumeeVive(force){
    var C = fumeeC(), v = state.vehicle || null, S = C.S, tN = nowMs();
    if (force || !S || S.v !== v || tN - S.t >= FUMEE_K().cache || tN < S.t) C.S = S = fumeeModele(v);
    return S;
  }
  /* Le facteur de la suie qui SORT : la reglette de la pompe (et la carte) fois ce que le filtre a particules laisse passer. */
  function facteurSuieSortie(v){
    var k = facteurSuie(v), p = antipPassageSuie(v);
    return (p === 1) ? k : k * p;
  }
  /* V1.1.0.69 : LE MANQUE D'AIR QUI FAIT FUMER UN TURBO DIESEL. manqueAirDiesel juge la pression contre la pression MAXI de la
     fiche : a charge partielle stabilisee la pression visee est partielle, et ce « manque » restait de 0,35 a 0,81 en croisiere -
     un diesel en bonne sante fumait noir a 90 km/h tenus. Ici, la part de l'air que DEMANDE la pedale et qui n'est pas encore la :
     pied au plancher, la loi d'avant au bit pres ; dans le trou du turbo (la pression monte, ou un regime trop bas pour qu'elle
     vienne), le noir reste ; en croisiere tenue, l'air est la. Un atmo garde sa loi (0 a 0,03 en croisiere). L'EGT ne lit pas
     cette fonction : elle garde manqueAirDiesel. */
  function manqueAirFumee(v, gaz, mB){
    if (!v || !suralimente(v)) return mB;
    var b = Math.min(1, Math.max(0, (state.boostPressure || 0) / Math.max(0.05, v.turboBar)));
    var mq = (gaz - b) / Math.max(FUMEE_K().manqueG, gaz);
    return n2oManqueAirDiesel(v, mq < 0 ? 0 : (mq > 1 ? 1 : mq));     // V1.1.99 (etape 10) : l'oxygene du nitro, comme manqueAirDiesel (pied au plancher, les deux restent egaux)
  }
  /* LE VOILE DE CHALEUR D'UNE TURBINE : l'air qui tremble derriere la tuyere. Un grain de vapeur tres clair par sortie, toutes les
     200 ms au plus, qui recule vite et s'efface en une demi-seconde : la case vapeur de la planche suffit, aucun dessin nouveau. */
  function emitChaleur(){
    if (reducedMotion || !vueSuivi()) return;
    var v = state.vehicle;
    if (!v || !estTurbine(v)) return;
    var S = fumeeVive();
    if (!(S.chaleur > 0)) return;
    var C = fumeeC(), tN = nowMs();
    if (tN - C.dernChaleur < 200 && tN >= C.dernChaleur) return;
    C.dernChaleur = tN;
    if (!smoke.ctx) setupSmoke(); else ancreSiBesoin();
    if (smoke.sens >= 0) return;
    var largeur = (smoke.x1 - smoke.x0), sorties = sortiesEch(v);
    var vitM = Math.max(0, vitesseMonde() / 3.6), derive = 0.42 * (largeur / 1.85) * vitM;
    var pxmE = smoke.pxmEch || (largeur / 1.85), dE = smoke.dEch || 5.6, hE = smoke.hEch || 0.42 * dE;
    for (var so = 0; so < sorties.length && placeFumee(); so++){
      var g = {
        vapeur: true, monde: true,
        x: smoke.x0 + largeur * sorties[so] + (Math.random() - 0.5) * 4,
        y: smoke.yEch + Math.random() * 3,
        vx: 0, vy: 0,
        r: 10 + Math.random() * 6, vr: 40,
        vie: 0, max: 0.6,
        a: 0.05 + 0.05 * Math.min(1, S.chaleur),
        derive: derive * (0.8 + Math.random() * 0.4),
        ph: Math.random() * 6.283,
        vz: 6, tauJ: 0.2, aB: 0.6, tauH: 0.6,
        vxw: (Math.random() - 0.5) * 0.3 + (smoke.echLat || 0) * (1.6 + Math.random() * 0.6),
        wz: 0, wh: 0, wx: 0, vh: 0, yDer: 0, xOsc: 0,
        pxm: pxmE, d0: dE, hc: hE, cx: (smoke.x0 + smoke.x1) / 2
      };
      pousserParticule(g);
    }
    startSmokeLoop();
  }
  /* ===== LE JOINT DE CULASSE (V1.1.0.62) =====
     Le liquide au carter fumait blanc (V1.1.0.25), mais aucune panne ne l'amenait. Deux causes l'ouvrent, par pas de 0,1 s :
       - la SURCHAUFFE d'eau, dans la bande de degat (xe de 0 a 1 entre le degat et la casse) : 0,004 x xe au carre - au milieu
         de la bande, 0,30 en une trentaine de secondes ;
       - le CALAGE diesel trop tot de la carte : la moitie de l'usure que la carte en tire.
     A 0,10 un message, a 0,30 le bouton REPARER et l'alerte rouge ; la fumee blanche suit la fuite. La triche d'usure l'arrete ;
     REPARER et un vehicule pris en main le referment. La casse par surchauffe (130 degres) reste ce qu'elle est. */
  function jointFuitePas(xe, dCal){
    if (tricheUsure() || refroidiAir(state.vehicle)) return;     // V1.1.0.62 (correction) : refroidi par air, aucun liquide a faire passer
    var K = FUMEE_K(), d = 0;
    if (xe > 0) d += K.jointEau * xe * xe;
    if (dCal > 0) d += K.jointCal * dCal;
    if (!(d > 0)) return;
    var a = state.jointFuite || 0, n = Math.min(1, a + d);
    state.jointFuite = n;
    var C = fumeeC(), tN = nowMs();
    if (a < K.jointMsg && n >= K.jointMsg && !(tN - C.tJoint < 30000 && tN >= C.tJoint)){
      C.tJoint = tN;
      setStatus(t("JOINT DE CULASSE QUI FUIT - FUMEE BLANCHE, REPAREZ"), true);
    }
    if (a < K.jointRep && n >= K.jointRep) majBoutonStart();
  }
  /* Les crochets communs de l'echappement : ce qui se repare (le joint, puis l'antipollution), ce qui est abime, ce qui est rouge. */
  function remiseANeufEchappement(v, genre){
    var ab = (state.jointFuite || 0) > 0.001;
    state.jointFuite = 0;
    var a = antipNeuf(v, genre);
    return ab || !!a;
  }
  function echappementAbime(){ return (state.jointFuite || 0) >= FUMEE_K().jointRep || antipAbime(); }
