    var O = { cat: 0, lam: 0, fe: 0, fd: 0, egr: 0, uree: 0 }, poss = {}, liste = [], an = anneeFiche(v), i, p;
    var An = { cat: 0, lam: 0, fe: 0, fd: 0, egr: 0, uree: 0 }, S = v.antipSerie ? antipSerieObjet(v.antipSerie) : null, serie = false;
