      /* Les facteurs quand la composante fait SEULE toute la difference (sonSil a +33 %, une piece a +66 %). */
      sonSil: { vol: 1.16, bright: 2.3,  noise: 2.99, pres: 2.26, pop: 1.6,  tau: 1 },     // sans silencieux
      catE:   { vol: 1.25, bright: 3.35, noise: 6.51, pres: 3.23, pop: 5.06, tau: 0.66 },     // catalyseur d'une essence, ou d'un deux-roues
      fe:     { vol: 1.25, bright: 3.35, noise: 6.51, pres: 3.23, pop: 1,    tau: 0.89 },     // filtre d'une essence a injection directe
      catD:   { vol: 2.1,  bright: 3.2,  noise: 3.8,  pres: 1.2,  pop: 1,    tau: 1 },     // catalyseur d'oxydation d'un gazole
      fd:     { vol: 2.1,  bright: 3.2,  noise: 3.8,  pres: 1.2,  pop: 1,    tau: 0.72 },     // filtre d'un gazole
