        var chaud = tu.gaz === 'ech', pts = tu.pts.map(PX), Rp = tu.r * ech;
        tubeCoupe(ctx, pts, Rp, chaud ? (tu.pal || PAL_ECH) : PAL_ADM, tu.prof, chaud ? '#ffd2a0' : eclA, chaud ? aE : aA, ph, tu.coude);     // V1.2.1 : tu.pal, la seconde volute
        /* V1.1.0.40 : et il suit l'EGT - max(gaz x 0,6 ; suraEgt) : encore rouge quelques secondes apres le lever de pied, jaune
           au-dela du seuil de degat (lueurEchCoupe). */
