    /* V1.0.89.255 : la surface du theme et la mise en page des bancs, posees une fois pour les quatre dessins du volet.
       Les bandeaux sont un peu moins hauts que ceux des bancs : ici c'est le moteur qu'on regarde, pas une echelle. */
    var LC = bancCadre(ctx, W, H);
    LC.y0 = Math.round(LC.f * 1.8);
    LC.y1 = H - Math.round(LC.f * 1.6);
