    var rotSura = rotStar && !suraCacheeCoupe() && suralimente(v);   // V1.1.0.7 : le compresseur tourne avec l'etoile (V1.1.0.25 : casse, montre)

    var r = g.manivelle, L = g.bielle, al = g.alesage;
    /* V1.0.89.267 : les degats, et le cylindre qui lache - le plus proche, pour qu'on le voie. */
    var DG = degatsCoupe(), cDeg = null;
    if (DG) g.cylindres.forEach(function(c){ if (!cDeg || c.prof > cDeg.prof) cDeg = c; });
    /* V1.1.0.32 : le cylindre dont la soupape d'echappement a brule - celui de devant, pour qu'on le voie. */
    var cMort = null;
    if (state.soupapeBrulee && g.cames !== 'rotv') g.cylindres.forEach(function(c){ if (!cMort || c.prof > cMort.prof) cMort = c; });     // V1.1.0.44 : une valve rotative n'a pas de soupape
