    var pasP = (g.profMax > 0) ? Math.min(al * 0.30, al * 1.15 / g.profMax) : 0;
    var FUX = 0.94 * pasP, FUY = -0.34 * pasP;

    /* ===== DEUX VILEBREQUINS, ET PAS TOUJOURS DANS LE MEME SENS =====
       Le H superpose ses deux etages de boxer : ses cylindres sont couches, l'ecart
       entre arbres est donc VERTICAL. Le U pose ses deux blocs cote a cote : ses
       cylindres sont debout, l'ecart est HORIZONTAL. C'est la meme piece — deux
       vilebrequins accouples — vue depuis deux moteurs qui ne se ressemblent pas, et
       un ecart pose une fois pour toutes en hauteur aurait empile les deux blocs d'un
       U l'un sur l'autre : la silhouette d'un H, c'est-a-dire d'un autre moteur. */
    var sepVile = (g.rangs.some(function(q){ return q.vile === 1; })) ? (al * 1.9) : 0;
    var dirVile = (g.arch === 'U') ? [1, 0] : [0, 1];
