      var voir = derriere || devant, detail = devant && lodD >= 1;
      var lwT = Math.max(0.8, lg * 1.2), lwH = Math.max(1.2, lg * 2.6), lwB = Math.max(0.8, lg * 1.1);
      var lwC = Math.max(1.2, 0.055 * K * ech), lwTg = Math.max(1, 0.04 * K * ech), lwP = Math.max(1.5, 0.10 * K * ech);
      var tiges = [], tetes = [], barres = [], ombr = [], ress = [];
