    var aq = 1 - K * K, bq = 2 * rg + 2 * D * K, cq = rg * rg - D * D - Y, disc = bq * bq - 4 * aq * cq;
    if (disc >= 0){
      var r1 = (-bq + Math.sqrt(disc)) / (2 * aq), r2 = (-bq - Math.sqrt(disc)) / (2 * aq);
      ri = (r1 > 0 && (r1 < r2 || !(r2 > 0))) ? r1 : r2;
    }
