    if (E.det === 0){ ctx.strokeStyle = stirRgbF([70, 77, 76], prof); ctx.lineWidth = 0.22; ctx.beginPath(); ctx.moveTo(p0[0], p0[1]); ctx.lineTo(p1[0], p1[1]); ctx.stroke(); return; }
