    G.rE = rE; G.LE = lo; G.LrB = 0; var xeMax = 0;
    for (j2 = 0; j2 < 144; j2++){ var ph2 = j2 * Math.PI / 72, xe = xeF(ph2, rE, G.LE); G.LrB = Math.max(G.LrB, coursePiston(ph2, r, L) + hj + 0.06 - xe); xeMax = Math.max(xeMax, xe); }
