      if (a.role === 'chaud'){ Vc = G.dHi.chaud - pa - hj - G.cap; Vf = G.dHi[b.role] - pb - hj; }
      else if (a.role === 'double'){ Vc = G.dHi.double - (pa + G.LrX + G.hpD + G.capD); Vf = pb + G.LrX - G.dGl; }
      else { Vc = pa + G.LrX - G.dGl; Vf = G.dHi[b.role] - pb - hj; }     // gamma : du fond froid du deplaceur a l'espace du cylindre moteur
