        var a = Math.min(0.95, (DG.u - 0.45) * 2), f0 = P.fis, fd = P.fisD || [0, 1], fn = Math.hypot(fd[0], fd[1]) || 1, dx = fd[0] / fn, dy = fd[1] / fn, pts = [], j;
