      var fort = Math.max(0.15, 1 - DG.age / 20), lT = Math.max(5, 0.25 * S), hT = Math.max(2.5, 0.1 * S), i;
      var h2 = (E.v.stirGaz === 'hydrogene') && E.tC > 500, cJ = h2 ? '150,190,255' : '214,232,255';
      var gs = ctx.createRadialGradient(tp[0], tp[1], 0, tp[0], tp[1], lT * 2);
