        if (detH === 2){ ctx.fillStyle = tc(T.acierF); ctx.fillRect(-0.68, 0.06, 1.36, 0.05); [-1, 1].forEach(function(sg){ stirBoulonF(ctx, E, sg * 0.64, 0.085, 0.028, prof); }); }
