    var perce = casse && (DG.mode === 'rechauffeur' || /^RECHAUFFEUR PERCE/.test(motif) || motif.indexOf(t("RECHAUFFEUR PERCE - TROP CHAUD")) === 0);
    var tC = isFinite(st.tChaud) ? st.tChaud : tempAmbiante();
    var E = { v: v, G: G, T: TEINTES_COUPE, now: now, psi: coupe.psi || 0, tourne: tourne, tC: tC, h: chaleurStirlingF(v), st: st,
              feu: (st.bruleur && !casse) ? Math.max(0.15, Math.min(1, st.feu || 0)) : 0, comb: STIR_FLAMME[v.stirComb] ? v.stirComb : 'diesel',
              DG: DG, u: DG ? Math.max(0, Math.min(1, DG.u)) : 0, casse: casse, perce: perce,
              mode: (casse && !perce) ? ((DG.mode === 'sorti') ? 'sorti' : 'carter') : null,
              bleu: casse && DG.cause === 'huile', eau: casse && DG.cause === 'eau', flux: tourne ? 1 : 0, pts: {}, det: 2 };
