    ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, r * 0.96, angC - 0.95, angC + 0.95); ctx.closePath();
    ctx.fillStyle = teinteCoupe(T.acierF, prof); ctx.fill(); if (det > 0){ ctx.strokeStyle = teinteCoupe(T.filet, prof); ctx.lineWidth = E.lw; ctx.stroke(); }
    if (riche){ ctx.beginPath(); ctx.arc(-M[0] * 0.62, -M[1] * 0.62, r * 0.11, 0, 2 * Math.PI); ctx.fillStyle = T.creux; ctx.fill(); }     // le percage d'equilibrage
