    var FX = 0.94 * pas, FY = -0.34 * pas;
    // V1.0.89.255 : le carter plein deborde la trochoide de 14 % ; le cadrage le compte.
    var CARTER_ROTOR = 1.14;
    // En hauteur, c'est la bougie qui depasse le plus : 1,05 rayon au-dessus de l'axe, le carter a peine moins dessous.
    var bx0 = -(1 + WANKEL_E) * CARTER_ROTOR, bx1 = (1 + WANKEL_E) * CARTER_ROTOR + FX * (N - 1);
    var by0 = -1.05 + Math.min(0, FY * (N - 1)), by1 = 1.05 + Math.max(0, FY * (N - 1));
