    traceFixe(tableBoitier(0, Math.PI * 2, 0.05), carterK);
    ctx.closePath();
    ctx.fillStyle = tc(T.bloc); ctx.fill();
    ctx.strokeStyle = tc(T.arete); ctx.lineWidth = lg; ctx.stroke();
    ctx.fillStyle = tc(T.creux);
