      var tps = Math.floor(p / 270) % 4;                     // 0 detente ... 3 compression
      if (estVapeur(state.vehicle)){     // V1.1.0.54 : le detendeur - deux cycles par tour de face
        var qV = p % 540;
        tps = (qV < 270) ? ((qV < 270 * admissionVapeur(state.vehicle)) ? 2 : 0) : ((qV < 500) ? 1 : 3);
      }
      ctx.beginPath();
      var d0 = pointBoitier(f0), q0 = P(d0[0], d0[1]);
      ctx.moveTo(q0[0], q0[1]);
