      if (fam === 'electrique'){ S.quoi = 'piece'; S.piece = 'bobinages'; libs = t("BOBINAGE BRULE"); }
      else if (fam === 'turbine' || (fam === 'turbineVapeur' && mo !== 'chaudiere')){ S.quoi = 'piece'; S.piece = 'rotor'; libs = t("AUBES ARRACHEES"); }
