    S.signe = !mC ? '' : (casseBelier() ? 'belier' : (cartoMotifEst(String(casseVu.motif || ''), "NITRO - RETOUR DE FLAMME") ? 'retourAdm' : ''));
    S.air = !!(v && moteurAAir(v));
