    if (id === m3d.vuId && mc === m3d.vuCasse && tc === m3d.vuTurbo && t0 === m3d.vuT0 && sb === m3d.vuSoup) return;
    if ((id !== m3d.vuId && id) || (t0 !== m3d.vuT0 && t0)) m3d.casseDirect = true;
