    /* A l'ouverture, la premiere maquette (construire, puis la compilation des matieres a la premiere image) attend que le rail ait
       fini de glisser (0,26 s) : le glissement reste fluide, le moteur apparait juste apres. */
    if (!m3d.groupe && tps - m3d.tOuvert < 300) return;
    if (tps - m3d.tDesc > 1000) majModeleM3d(v, tps);     // une fiche modifiee, une autre machine, LIGNE COMPLETE, la qualite
    if (!m3d.groupe || hudPage !== 5) return;
    var R = (rendu3dM.hote && !hoteVolet3d(rendu3dM.hote)) ? null : rendu3dMPrendre(els.hudPanel6, gestesM3d);     // V1.2.2 (CAPOT 3D) : D35
