    cam.position.set(m3d.cx + Dd * Math.sin(y) * Math.cos(p), m3d.cy + Dd * Math.sin(p), m3d.cz + Dd * Math.cos(y) * Math.cos(p));
    cam.lookAt(m3d.cx, m3d.cy, m3d.cz);
