             monte: null, type: null, src: null, aPos: null, aCol: null, aA: null, aS: null, flamme: 0, coups: 0, tCh: 0, tPurge: 0,
             cleC: '', rgb: [0, 0, 0], S: 0.08, kTaille: 1.5, _v: null, _d: null,
