      vertexShader: 'attribute vec3 iPos; attribute vec3 iCol; attribute float iA; attribute float iS; varying vec2 vUv; varying vec3 vCol; varying float vA;' +
        'void main(){ vUv = uv; vCol = iCol; vA = iA; vec4 mv = modelViewMatrix * vec4(iPos, 1.0); mv.xy += position.xy * iS; gl_Position = projectionMatrix * mv; }',
      fragmentShader: 'varying vec2 vUv; varying vec3 vCol; varying float vA;' +
        'void main(){ float r = length(vUv - vec2(0.5)) * 2.0; if (r >= 1.0) discard;' +
        ' float k = (r < 0.55) ? 1.0 - 0.45 * r / 0.55 : 0.55 * (1.0 - (r - 0.55) / 0.45); gl_FragColor = vec4(vCol, vA * k); }',
