            F.acc[k] -= 1;
            i = L.n++;
            var dx = D.x + (Math.random() - 0.5) * 0.10, dy = D.y + (Math.random() - 0.5) * 0.10, dz = D.z + (Math.random() - 0.5) * 0.10;
            var l = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1, sp = (24 + 30 * Lk) * (0.8 + 0.4 * Math.random()) * F.S / l;
            L.x[i] = P.x; L.y[i] = P.y; L.z[i] = P.z;     // a la bouche meme
            L.vx[i] = dx * sp + F.vCar.x; L.vy[i] = dy * sp + F.vCar.y; L.vz[i] = dz * sp + F.vCar.z;
            L.age[i] = -Math.random() * Math.min(dt, 0.05);     // naissances etalees sur l'image : un jet continu, pas des paquets
            L.vie[i] = (0.09 + 0.10 * Lk) * (0.8 + 0.4 * Math.random()) * (0.6 + 0.4 * lev);
