            var compte = fumee3dCompte(F, k);
            while (F.acc[k] >= 1 && compte < cap){ if (!fumee3dNaitre(F, k, so, pr.el, pr.vie, pr.taille, pr.a, c3[0], c3[1], c3[2], 0)) break; F.acc[k] -= 1; compte++; }
