        var ch = state.chaud, nom = Math.max(2, v.chaudBar || 20), pres = Math.max(0, Math.min(1.2, (ch.bar || 0) / nom));
        var flux = (Math.abs(state.rpm || 0) > 1) ? Math.max(0, Math.min(1, throttleCmd() * pres)) : 0;
        var tN = performance.now(), feuCh = ch.foyer && (v.combustible === 'charbon' || v.combustible === 'bois');
        var coups = 0;
