          if (sv.genre !== 'vapeur' && sv.genre !== 'foyer') continue;
          var cv = fumee3dCompte(F, k);
          if (souffle && continu && cv < cap){ F.acc[k] += (8 + 10 * flux) * dt; while (F.acc[k] >= 1 && cv < cap){ fumee3dNaitre(F, k, sv, 2.5 + 3 * flux, 1.3, 1.05, 0.25 + 0.55 * flux, 0.925, 0.937, 0.953, 2); F.acc[k] -= 1; cv++; } }
