          if (sv.genre === 'foyer' && feuCh && tN - F.tCh > 350 && cv < cap){ fumee3dNaitre(F, k, sv, 1.5, 2.2, 1.2, 0.12 + 0.25 * Math.max(0, Math.min(1, ch.feu || 0)), 0.745, 0.749, 0.745, 0); F.tCh = tN; }
