        if (fB > 0.2 && tP - F.tPurge > 70){ F.tPurge = tP; fumee3dNaitre(F, 255, F.entree, 4 + 3 * fB, 1.1, 1.6, 0.5 + 0.2 * fB, 0.925, 0.937, 0.953, 2); }
