    if (genre === 'nu') return (d.arch === 'B' || d.arch === 'H') ? ['long', 'trans'] : ['trans', 'long'];
    var cle = '';
    try { cle = String(cle3dDe(v) || ''); } catch (e){ cle = ''; }
    if (CAPOT_AUTO[cle] && comp.cote !== 'ar' && String(v.positionMoteur || 'avant') === 'avant' && String(v.transmission || 'arriere') === 'avant') return ['trans', 'long'];
    return ['long', 'trans'];
