    try { scn = (R3 && typeof R3.voitureScene === 'function') ? R3.voitureScene() : null; } catch (e){ scn = null; }
    if (!scn || reducedMotion){ f7m.n = 0; if (f7m.mesh) f7m.geo.instanceCount = 0; return; }
    if (!f7m.mesh || f7m.scene !== scn){ if (!f7mCreer(scn)) return; }
    if (state.vehicle !== f7m.v){ f7m.v = state.vehicle; f7m.n = 0; }
    var ob = src && src.ob, bx = 0, bz = 1, lx = 1, lz = 0;
