      var dx = X.px[i] - cx, dy = X.py[i] - cy, dz = X.pz[i] - cz, d = dx * dx + dy * dy + dz * dz;
      var b = nv - 1;
      while (b >= 0 && X.dist[b] < d){ X.ordre[b + 1] = X.ordre[b]; X.dist[b + 1] = X.dist[b]; b--; }
      X.ordre[b + 1] = i; X.dist[b + 1] = d; nv++;
