        X.wh[j] = X.wh[i]; X.vh[j] = X.vh[i]; X.ab[j] = X.ab[i]; X.th[j] = X.th[i]; X.wx[j] = X.wx[i]; X.vx[j] = X.vx[i];
        X.osc[j] = X.osc[i]; X.ph[j] = X.ph[i]; X.rb[j] = X.rb[i]; X.vr[j] = X.vr[i]; X.dv[j] = X.dv[i]; X.dr[j] = X.dr[i];
        X.db[j] = X.db[i]; X.vie[j] = X.vie[i]; X.max[j] = X.max[i]; X.a[j] = X.a[i];
        X.genre[j] = X.genre[i]; X.teinte[j] = X.teinte[i]; X.bouf[j] = X.bouf[i]; X.nl[j] = X.nl[i];
        for (var l = 0; l < 6; l++) X.lob[j * 6 + l] = X.lob[i * 6 + l];
