                 sE: null, drv: null, ex: null, ez: null, rv: null, aE: null, taux: 0, nes: 0, cpt: [0, 0, 0, 0, 0, 0, 0, 0],     // V1.3.1 (FUMEE EN ORBITE), corrections
                 plus: null, aPos: null, aR: null, aA: null, aC1: null, aC2: null, aG: null, aO: null, T: [0, 0, 0, 0, 0, 0],
