  var FUM_ORB_VUE = 1;                          // F-D25 (0 : la croissance de derive entiere, comme avant)
  var FUM_ORB_ECLOS = 0.01;                     // F-D28 (0 : l'eclosion du calque, comme avant)
  var FUM_ORB_PERSP = 1;                        // F-D29 (0 : la perspective de l'approche entiere, comme avant)
