                 yaw: -35, pitch: 18, zoom: 1, auto: true, doigts: [], pinch: 0, zoom0: 1, psi: 0, periode: 180, visuRot: 1, rpmVitrine: 800,
                 cx: 0, cy: 0, cz: 0, rc: 0, cadre0: true, tCache: 0, tTexte: -1e9, mesure: 0, vu: true, libT: null, routeArretee: false,
                 w: 0, h: 0, mw: 0, mh: 0, aide: true, aideT: 0, textes: { monte: null, dims: null, aide: null },
