  function assNomEtape(E){ return (E.cle === 'bilan') ? tc('ASSEMBLER', 'BILAN') : ((E.cle === 'cotes') ? tc('ASSEMBLER', 'COTES') : t(E.nom)); }     // V1.2.2 (ASSEMBLER L2) : COTES aussi
