    if (ass3d.suivre && ass3d.montageOk){
      var Et = null;
      try { Et = Moteur3D.montageEtat(g); } catch (e){ Et = null; }
      enCours = !!(Et && Et.enCours);
      if (!enCours) ass3d.suivre = false;     // une image encore (sale), puis plus rien tant que rien ne bouge
      /* V1.2.2 (ASSEMBLER L1, reprise) : toutes les pieces posees (fin : il ne reste que leur teinte), la camera glisse vers le cadre du
         repos (le moteur pose remplit le cadre) - le glissement tient dans la teinte : a la fin de la sequence, plus rien ne bouge */
      if ((!enCours || (Et && ass3d.cadArr && Et.arrivee >= ass3d.cadArr.fin)) && ass3d.cadArr && ass3d.cad === ass3d.cadArr && ass3d.cadRepos){ ass3d.cad = ass3d.cadRepos; ass3d.cadArr = null; ass3d.sale = true; }
    }
    if (!(ass3d.sale || enCours || ass3d.cible || ass3d.camBouge || ass3d.doigts.length || ass3d.auto || ass3d.tourner || AS)) return;
    var R = rendu3dMPrendre(H, gestesAss3d);
    if (!R || !R.ren){ if (m3d.echec){ H.classList.add('hidden'); if (H.__rang) H.__rang.classList.add('hidden'); } return; }
    reglerFinesseM3d(dtMs);
    var dpr = dprM3d(), w = Math.max(1, ass3d.mw), h = Math.max(1, ass3d.mh);
    if (w !== R.w || h !== R.h || dpr !== R.dpr){ R.w = w; R.h = h; R.dpr = dpr; R.ren.setPixelRatio(dpr); R.ren.setSize(w, h, false); }
    if (w !== ass3d.w || h !== ass3d.h){ ass3d.w = w; ass3d.h = h; ass3d.cam.aspect = w / h; ass3d.cam.updateProjectionMatrix(); }
    /* l'angle : TOURNER A LA MAIN (120 degres par seconde, sans combustion) ; demarre, le regime de son son, au ralenti a l'oeil de la
       vue 3D (periodeVisuM3d : pas de stroboscope) ; sinon il reste ou il est */
    if (AS){
      var V = Math.max(0, AS.rpm || 0) * 6 * ass3d.visuRot, P = ass3d.periode;
      ass3d.psi = (ass3d.psi + pasReelM3d(V, dt, P)) % 720;     // V1.2.3 (SANS RALENTI) : le vrai regime
    } else if (ass3d.tourner) ass3d.psi = (ass3d.psi + 120 * dt) % 720;
    var o = ass3d.opts;
    o.psi = ass3d.psi; o.vue = ass3d.transp ? 'transparence' : 'assemblee'; o.eclat = 0;     // V1.2.5 (TRANSPARENCE ASSEMBLER ET SWAP)
    o.charge = chargeApercu(AS);
    o.tourne = !!(AS && AS.etat === 'marche');
    o.boost = (AS && ass3d.turboBar > 0) ? Math.max(0, Math.min(1, (AS.boost || 0) / ass3d.turboBar)) : 0;
    Moteur3D.animer(g, tps / 1000, 0, o);     // le temps fait avancer les arrivees du montage
