  /* LA CAMERA : en orbite autour du moteur complet (son cadrage, garde), a la distance qui le fait tenir dans le cadre (zoom du joueur
     garde) ; elle glisse vers l'angle conseille au changement d'etape. */
  function ass3dCamera(dt, tps){
    var cam = ass3d.cam, K = ass3d.cad, r = K.rayon;
    if (ass3d.cible){
      var Cb = ass3d.cible, u = Math.max(0, Math.min(1, (tps - Cb.t0) / 600)), e = 1 - (1 - u) * (1 - u) * (1 - u);
      var dy = ((((Cb.y1 - Cb.y0) % 360) + 540) % 360) - 180;
      ass3d.yaw = Cb.y0 + dy * e; ass3d.pitch = Cb.p0 + (Cb.p1 - Cb.p0) * e;
      if (u >= 1) ass3d.cible = null;
    } else if (ass3d.auto) ass3d.yaw += dt * 20;
    var k = ass3d.cadre0 ? 1 : Math.min(1, dt * 7);
    ass3d.cadre0 = false;
    var fv = cam.fov * Math.PI / 360, fh = Math.atan(Math.tan(fv) * cam.aspect);
    /* V1.2.2 (ASSEMBLER L1, reprise) : la distance qui fait tenir le CADRE DE L'ETAPE (ses coins, rendus par la maquette) dans l'image,
       a ce tangage et pour tout lacet (Moteur3D.distanceCadre : rien n'est coupe quand on tourne, le zoom ne respire pas), refaite
       quand le cadre, le tangage (2 degres) ou la forme de l'image changent ; sans coins (maquette 0.6) : la sphere, comme avant */
    var Dt;
    if (K.coins && window.Moteur3D && Moteur3D.distanceCadre){
      if (K.dFit === undefined || Math.abs(K.pFit - ass3d.pitch) > 2 || K.aFit !== cam.aspect){ K.dFit = Moteur3D.distanceCadre(K.coins, K.centre, ass3d.pitch, cam.fov, cam.aspect, 0.92); K.pFit = ass3d.pitch; K.aFit = cam.aspect; }
      Dt = K.dFit;
    } else Dt = r * 0.84 / Math.sin(Math.min(fv, fh));
    if (!(Dt > 0)) Dt = r * 0.84 / Math.sin(Math.min(fv, fh));
    var ex = K.centre[0] - ass3d.cx, ey = K.centre[1] - ass3d.cy, ez = K.centre[2] - ass3d.cz, er = r - ass3d.rc, ed = Dt - ass3d.dc;
    ass3d.cx += ex * k; ass3d.cy += ey * k; ass3d.cz += ez * k; ass3d.rc += er * k; ass3d.dc += ed * k;
    ass3d.camBouge = (Math.abs(ex) + Math.abs(ey) + Math.abs(ez) + Math.abs(er)) * (1 - k) > r * 1e-3 || Math.abs(ed) * (1 - k) > Dt * 1e-3;
    var D = Math.max(0.05, ass3d.dc / ass3d.zoom);
    var y = ass3d.yaw * Math.PI / 180, p = ass3d.pitch * Math.PI / 180;
    cam.position.set(ass3d.cx + D * Math.sin(y) * Math.cos(p), ass3d.cy + D * Math.sin(p), ass3d.cz + D * Math.cos(y) * Math.cos(p));
    cam.lookAt(ass3d.cx, ass3d.cy, ass3d.cz);
    /* V1.2.2 (ASSEMBLER L1, reprise) : les plans de coupe gardent le moteur COMPLET et son bati (le cadre d'une etape est plus petit) */
    var rP = Math.max(r, ass3d.cadPlein ? ass3d.cadPlein.rayon : 0);
    var near = Math.max(0.005, D - rP * 2.5), far = D + rP * 3.5;
    if (Math.abs(near - cam.near) > cam.near * 0.2 || Math.abs(far - cam.far) > cam.far * 0.2){ cam.near = near; cam.far = far; cam.updateProjectionMatrix(); }
  }

  /* ----- les courbes en grand ----- */
  var assGrand = { el: null, cv: null, etat: {} };
  function assGrandOuvert(){ return !!(assGrand.el && !assGrand.el.classList.contains('hidden')); }
  function assGrandOuvrir(){
    var v = state.vehicle, A = prepVue.ass;
    if (!v || !A) return;
    if (!assGrand.el){
      var ov = document.createElement('div');
      ov.className = 'modalOverlay grandCourbes hidden'; ov.id = 'assGrandPanel';
      ov.innerHTML = '<div class="grandCourbesBox"><div class="grandCourbesTete"><div class="modalTitle" id="assGrandTitre"></div>'
        + '<div class="grandCourbesSous" id="assGrandSous"></div></div><div class="grandCourbesToile"><canvas id="assGrandCv"></canvas></div>'
        + '<div class="grandCourbesLegende" id="assGrandLegende"></div><div class="grandCourbesTable" id="assGrandTable"></div>'
        + '<div class="modalActions"><button class="bigbtn primaire" id="btnAssGrandMonter"></button><button class="bigbtn" id="btnAssGrandFermer"></button></div></div>';
      document.body.appendChild(ov);
      assGrand.el = ov; assGrand.cv = document.getElementById('assGrandCv');
      bindLigne(document.getElementById('btnAssGrandFermer'), function(){ ov.classList.add('hidden'); });
      bindLigne(document.getElementById('btnAssGrandMonter'), function(){ ov.classList.add('hidden'); assMonter(); });
    }
    assGrand.el.classList.remove('hidden');
    assGrandRemplir();
    requestAnimationFrame(assGrandPeindre);
  }
  function assGrandRemplir(){
    var v = state.vehicle, A = prepVue.ass;
    if (!assGrand.el || !v || !A) return;
    var C = assCalcul(A.d, v), m = C.m, L = C.lim;
    document.getElementById('assGrandTitre').textContent = t("COURBES");
    document.getElementById('assGrandSous').textContent = String(m.typeMoteur || '') + '  -  ' + t("MOTEUR NEUF, CHAUD, 20 DEG, NIVEAU DE LA MER");
    document.getElementById('assGrandLegende').innerHTML = '<span><i style="border-color:' + NEO.accent + '"></i>' + t("PUISSANCE") + '</span>'
      + '<span><i style="border-color:' + NEO.ambre + '"></i>' + t("COUPLE") + '</span>'
      + '<span><i class="tirets" style="border-color:rgba(233,237,236,0.45)"></i>' + t("MOTEUR MONTE") + '</span>'
      + '<span><i style="border-color:#ff5a4f"></i>' + t("LIMITE DES PIECES") + '</span>';
    var n2 = 0; C.pts.forEach(function(q){ if (Math.abs(q.x - 2000) < 60) n2 = q.nm; });
    if (!n2) n2 = coupleEffectif(m, 2000);
    var h = grandCourbesLigne(t("PUISSANCE"), t("{0} A {1}", U.txt('puissance', C.pk.p.ch), assNb(C.pk.p.x) + ' ' + t("TR")))
          + grandCourbesLigne(t("COUPLE"), t("{0} A {1}", U.txt('couple', C.pk.c.nm), assNb(C.pk.c.x) + ' ' + t("TR")))
          + grandCourbesLigne(t("COUPLE A 2000 TR"), U.txt('couple', n2))
          + grandCourbesLigne(t("RUPTEUR"), assNb(m.rupteur) + ' ' + t("TR") + ' (' + t("UTILE {0}", assNb(Math.round(C.B.r.details.rupUtile / 50) * 50)) + ')')
          + grandCourbesLigne(t("REGIME MAXI DES PIECES"), assNb(L.tr) + ' ' + t("TR") + ' - ' + t(L.trP))
          + grandCourbesLigne(t("COUPLE MAXI DES PIECES"), U.txt('couple', L.nm) + ' - ' + t(L.nmP));
    document.getElementById('assGrandTable').innerHTML = h;
    document.getElementById('btnAssGrandMonter').textContent = t("MONTER CE MOTEUR");
    document.getElementById('btnAssGrandFermer').textContent = t("FERMER");
  }
  function assGrandPeindre(){
    var v = state.vehicle, A = prepVue.ass;
    if (!assGrandOuvert() || !v || !A) return;
    var C = assCalcul(A.d, v), g = assApercu(v), pkG = assPics(g);
    tracerCourbesGrand(assGrand.cv, assGrand.etat, { axe: 'rpm', a: Math.min(C.m.idle, v.idle || C.m.idle),
      b: Math.max(C.m.rupteur, C.lim.tr, v.rupteur || 0) * 1.03,
      p: Math.max(C.pk.p.ch, pkG.p.ch) * 1.15, c: Math.max(C.pk.c.nm, pkG.c.nm) * 1.25, limTr: C.lim.tr, limNm: C.lim.nm,
      series: [{ pts: g, cp: 'rgba(233,237,236,0.4)', cc: 'rgba(233,237,236,0.4)', lw: 1.6, tirets: [5, 5] },
               { pts: C.pts, cp: NEO.accent, cc: NEO.ambre, lw: 3.2 }],
      pics: { p: C.pk.p, c: C.pk.c } });
  }
  (function(){
    var rep = function(){ if (assGrandOuvert()) requestAnimationFrame(assGrandPeindre); };
    window.addEventListener('resize', rep); window.addEventListener('orientationchange', rep);
    document.addEventListener('visibilitychange', function(){ if (!document.hidden) rep(); });
    surChangementLangue(function(){ if (assGrandOuvert()){ assGrandRemplir(); rep(); } });
    surChangementUnite(function(){ if (assGrandOuvert()){ assGrandRemplir(); rep(); } });
  })();

  /* =====================================================================================================================
     ===== V1.2.2 (ASSEMBLER L2) : LES REGLAGES EXPERTS - BAS MOTEUR, COTES, HAUT MOTEUR ===================================
     =====================================================================================================================
     Plan fige : travail/assembler-expert/plan-L2.md (section A, puis 0 a 16). Chaque reglage de la liste de l'auteur est UNE entree de
     ASS_REG : sa serie, ses bornes, ses voisins, son affichage. La valeur vit dans d.x[groupe][cle] (groupes bas, cotes, haut,
     respiration), ecrite seulement si elle differe de sa serie : un moteur sans d.x est EXACTEMENT celui de la 1.2.1 (calcul, sauvegarde,
     son, 3D). Les effets sont calcules en UN endroit, assRegEffets, par les seuls leviers que le jeu modelise deja (couple et regime tenus
     par piece, cliquetis et compression maxi, respiration, couple au ralenti, inertie, soupapes qui brulent, balayage, VVT, VVL), chacun
     plafonne ; PIECES les recoit et ne lit jamais cette table. La 3D suit la valeur (assRegDesc -> desc.x, contrat plan-L2 12) ; une valeur
     de serie se dessine comme en 1.2.1. Reglages refuses (plan-L2 L2-D12) : deport d'axe, angle des lumieres, nombre de palettes, masse
     libre ; bougies : L3 ; valve a l'echappement du deux-temps : l'atelier. */
  function assRegBorne(x, a, b){ return Math.max(a, Math.min(b, x)); }
  function assRegFo(x, pas){
    var dec = pas < 0.01 ? 3 : (pas < 0.1 ? 2 : (pas < 1 ? 1 : 0));
    return String(parseFloat((Math.round(x / pas) * pas).toFixed(dec))).replace('.', decLangue());
  }
  function assRegSigne(x, pas){ return (x > 1e-9 ? '+' : (x < -1e-9 ? '-' : '')) + assRegFo(Math.abs(x), pas); }
  /* Ce que la famille du brouillon permet : un objet de drapeaux, calcule a la demande (pur, sans vehicule) */
  function assRegK(d){
    var f = d.fam, et = assRadial(d), op = assOP(d), sp = assSansPiston(d);
    var K = { f: f, et: et, ro: f === 'RO', op: op, sp: sp, wk: f === 'WK', e4: f === 'E4', d4: f === 'D4', e2: f === 'E2', d2: f === 'D2',
              pis: !sp, ds: assDiesel(d), cames: d.cames || 'dohc', vpc: d.vpc || 2 };
    K.cl = (f === 'E4' || f === 'D4' || f === 'E2' || f === 'D2') && !et;     // un moteur a pistons « classique » : bloc, culasse, rangees
    K.sou = (f === 'E4' || f === 'D4' || f === 'RO');                         // des soupapes (etoile et rotary compris)
    K.ress = f === 'E4' && ['lat', 'ohv', 'sohc', 'dohc'].indexOf(K.cames) >= 0;
    K.calage = !sp && d.arch !== 'R' && d.cyl > 1 && f !== 'RO' && f !== 'OT' && !(et && etoileRangees(d.cyl, ass2T(d)).rangees === 1);
    var a = d.arch, n = d.cyl;
    K.paliers = (f === 'E4' || f === 'D4' || f === 'D2') && K.cl
      && ((a === 'I' && n >= 3) || (a === 'V' && n >= 6) || (a === 'VR' && n >= 5) || a === 'W' || (a === 'B' && n >= 4) || (a === 'U' && n >= 4));
    return K;
  }
  /* La matiere du bloc : 'alu' (et le carter ferme 'ferme', le magnesium 'mg'), 'fonte', 'vermic', 'acier' ; E2 : 'fonte' ou 'revetu' */
  function assRegMat(d){
    var b = d.p && d.p.bloc;
    if (d.fam === 'E4') return (b === 'fonte') ? 'fonte' : (b === 'magnesium' ? 'mg' : (b === 'ferme' ? 'ferme' : 'alu'));
    if (d.fam === 'D4') return (b === 'alu') ? 'alu' : (b === 'vermic' ? 'vermic' : 'fonte');
    if (d.fam === 'OT') return (b === 'alu') ? 'alu' : 'acier';
    if (d.fam === 'OP') return (b === 'acier') ? 'acier' : (b === 'vermic' ? 'vermic' : 'fonte');
    if (d.fam === 'E2') return (b === 'revetu') ? 'revetu' : 'fonte';
    return (b === 'vermic') ? 'vermic' : 'fonte';
  }
  function assRegAluChem(d){ var m = assRegMat(d); return m === 'alu' || m === 'mg' || m === 'ferme'; }
  /* Les rangees d'un moteur a pistons (pur : rangsCoupe et groupesRangsCoupe, les fonctions de la coupe) : le plus grand nombre de
     cylindres d'une rangee (ENTRAXE), et une culasse qui coiffe plusieurs rangees (VR, W : pas d'ANGLE DES SOUPAPES, comme la 3D). */
  var assRegGeoMemo = {};
  function assRegGeo(d){
    var cle = d.arch + ':' + d.cyl + ':' + (d.angleV || 0);
    if (assRegGeoMemo[cle]) return assRegGeoMemo[cle];
    var G = { rangMax: 1, culMulti: false };
    try {
      var g = rangsCoupe({ arch: d.arch, cyl: d.cyl, angleV: d.angleV, vilebrequin: 'regulier' }), n = {}, k;
      g.cylindres.forEach(function(c){ n[c.rang] = (n[c.rang] || 0) + 1; });
      for (k in n) if (n[k] > G.rangMax) G.rangMax = n[k];
      g.arch = d.arch;
      G.culMulti = groupesRangsCoupe(g).some(function(b){ return b.rangs.length > 1; });
    } catch (e){}
    return (assRegGeoMemo[cle] = G);
  }
  /* Les cames : la duree effective (celle de la carte, ou celle reglee), et ce qui s'interpole avec elle - la respiration s (le levier des
     cartes PROFIL), la levee de serie kL x diametre d'admission, l'ecart des cames de serie e0. */
  var ASS_REG_CAMES = { kL: [0.25, 0.27, 0.29, 0.31, 0.33], e0: [116, 112, 110, 108, 106] };
  function assRegInterp(cle, dur){
    var P = PIECES.PROFIL, V = (cle === 's') ? P.map(function(x){ return x.s; }) : ASS_REG_CAMES[cle], i;
    for (i = 0; i < P.length; i++) if (dur === P[i].deg) return V[i];
    if (dur <= P[0].deg) return V[0];
    if (dur >= P[P.length - 1].deg) return V[V.length - 1];
    for (i = 0; dur > P[i + 1].deg; i++);
    return V[i] + (dur - P[i].deg) / (P[i + 1].deg - P[i].deg) * (V[i + 1] - V[i]);
  }
  var ASS_REG_KA = { 2: 0.48, 3: 0.33, 4: 0.38, 5: 0.31, 6: 0.28 }, ASS_REG_KE = { 2: 0.40, 3: 0.42, 4: 0.32, 5: 0.33, 6: 0.25 };
  function assRegDA0(d){ return (ASS_REG_KA[Math.max(2, Math.min(6, d.vpc || 2))] || 0.38) * d.bore; }
  function assRegDE0(d){ return (ASS_REG_KE[Math.max(2, Math.min(6, d.vpc || 2))] || 0.32) * d.bore; }
  function assRegRap0(d){ return d.cames === 'ohv' ? 1.50 : (d.cames === 'sohc' ? 1.20 : 1); }
  function assRegCames(d){
    var carte = PIECES.parId(PIECES.PROFIL, d.profil), dur = assRegLu(d, 'duree');     // les valeurs RANGEES (les series se calculent ici)
    if (!(dur > 0)) dur = carte.deg;
    var L0 = assRegInterp('kL', dur) * assRegDA0(d), rot = d.cames === 'rotv';
    var lev = rot ? L0 : assRegLu(d, 'levee'), rap0 = assRegRap0(d), rap = (d.cames === 'ohv' || d.cames === 'sohc') ? assRegLu(d, 'rap') : rap0;
    if (!(lev > 0)) lev = L0;
    if (!(rap > 0)) rap = rap0;
    var Le = lev * rap / rap0, e0 = assRegInterp('e0', dur), e = assRegLu(d, 'ecart'), av = assRegLu(d, 'calCames') || 0;
    if (!(e > 0)) e = e0;
    return { carte: carte, dur: dur, kDur: dur / carte.deg, L0: L0, lev: lev, Le: Le, kL: Le / L0, rap: rap, rap0: rap0, e0: e0, e: e,
             dSep: e - e0, av: av };
  }
  /* La levee des soupapes au point mort haut, en part de la levee maxi (contrat plan-L2 12 : la MEME formule que les fenetres de la 3D).
     Serie : 0,0203. Borne : 0,07 (N29). Sans soupapes : 0. */
  function assRegLambda(kDur, dSep, av, kL){
    var w = 220 * kDur, cA = 460 + dSep - av, cE = 260 - dSep - av;
    function f(c){ var x = 360 - (c - w / 2); if (x <= 0 || x >= w) return 0; var s = Math.sin(Math.PI * x / w); return s * s; }
    return kL * Math.max(f(cA), f(cE));
  }
  function assRegLeveePMH(d){
    if (!assRegK(d).sou) return 0;
    var c = assRegCames(d);
    return assRegLambda(c.kDur, c.dSep, c.av, c.kL);
  }
  /* Le dome et la cuvette : des calottes (V = pi h (3 a2 + h2) / 6), la hauteur se tire du volume (Newton). Dome maxi : 0,055 B - 0,15 B x
     max(0, lambdaP - 0,02), de rayon de base 0,42 B ; cuvette maxi : 0,10 B de profondeur, rayon 0,38 B. mm et cm3. */
  function assRegCalotte(h, a){ return Math.PI * h * (3 * a * a + h * h) / 6 / 1000; }
  function assRegHCalotte(V, a){
    var h = V * 1000 * 2 / (Math.PI * a * a), i;
    for (i = 0; i < 30; i++){ var f = Math.PI * h * (3 * a * a + h * h) / 6 - V * 1000, df = Math.PI * (a * a + h * h) / 2; h -= f / df; }
    return Math.max(0, h);
  }
  function assRegDomeMax(d){ return assRegCalotte(Math.max(0, d.bore * (0.055 - 0.15 * Math.max(0, assRegLeveePMH(d) - 0.02))), 0.42 * d.bore); }
  function assRegCuvMax(d){ return assRegCalotte(0.10 * d.bore, 0.38 * d.bore); }
