  function assJsonTrie(o){
    if (o === null || typeof o !== 'object') return JSON.stringify(o);
    if (Object.prototype.toString.call(o) === '[object Array]') return '[' + o.map(assJsonTrie).join(',') + ']';
    return '{' + Object.keys(o).sort().filter(function(k){ return o[k] !== undefined; }).map(function(k){ return JSON.stringify(k) + ':' + assJsonTrie(o[k]); }).join(',') + '}';
  }
