    if (d.x.bas && d.x.bas.calage && d.x.bas.calage !== 'decale') delete d.x.bas.dec;
    /* la hauteur du bloc fixee : la hauteur de compression la suit (le kit « longue course »), dans ses bornes */
    if (assRegFixe(d, 'hBloc')){
      var r2 = d.stroke / 2, Lb = assRegValN(d, 'bielle'), hLo = Math.ceil((r2 + Lb + 0.25 * d.bore) / 0.5 - 1e-7) * 0.5, hHi = Math.floor((r2 + Lb + 0.50 * d.bore) / 0.5 + 1e-7) * 0.5;
      d.x.bas.hBloc = parseFloat(assRegBorne(d.x.bas.hBloc, hLo, Math.max(hLo, hHi)).toFixed(4));
      var hc1 = d.x.bas.hBloc - r2 - Lb;
      if (Math.abs(hc1 - 0.34 * d.bore) < 0.25 - 1e-9){ if (d.x.cotes) delete d.x.cotes.hc; }
      else assRegEcrire(d, 'cotes', 'hc', Math.round(hc1 * 1000) / 1000);
    } else if (hcDerive && d.x.cotes) delete d.x.cotes.hc;
    /* N29 : les soupapes ne touchent pas le piston au point mort haut - lambdaP <= 0,07, sinon les cames reviennent a la serie, une a une */
    if (K.sou){
      ['calCames', 'ecart', 'levee', 'rap', 'duree'].forEach(function(id){
        if (assRegLeveePMH(d) > 0.07 + 1e-9){ var g = d.x[ASS_REG_ID[id].grp]; if (g) delete g[id]; }
      });
    }
    /* le dome suit la levee au point mort haut ; la compression suit les volumes (plan-L2 3.7) */
    c = d.x.cotes;
    if (c && c.tete != null && assRegTeteCalotte(d, K)){
      var vMax = assRegDomeMax(d), vMin = -assRegCuvMax(d), pt = ASS_REG_ID.tete.pas(d);
      var tt = assRegBorne(c.tete, Math.ceil(vMin / pt - 1e-7) * pt, Math.floor(vMax / pt + 1e-7) * pt);
      tt = parseFloat(tt.toFixed(4));
      if (Math.abs(tt) < pt / 2 - 1e-9) delete c.tete; else c.tete = tt;
    }
    if (c && (c.tete != null || c.joint != null)){
      if (!(c.vCh > 0)) c.vCh = Math.round(assRegCompression(d).vCh * 1000) / 1000;     // une chambre absente (brouillon ecrit ailleurs) : tiree de la compression posee
      d.cr = Math.round(assRegCompression(d).cr * 10) / 10;
    } else if (c && c.vCh != null){
      d.cr = c.crA ? 0 : Math.round(assRegCompression(d).cr * 10) / 10;
      delete c.vCh; delete c.crA;
    }
    if (c && c.crA && !(c.vCh > 0)) delete c.crA;
    /* V1.2.2 (ASSEMBLER L3) : la taille de turbine posee est celle que le jeu fait tourner (d.mm, le chemin de la 1.2.1) ; des papillons
       individuels de serie plus larges que la pipe (un alesage qui a grandi sous une pipe fixee) sont recales sur elle ; puis la garde de
       cliquetis, EN DERNIER (M10) */
    var xr3 = d.x && d.x.respiration;
    if (xr3){
      if (xr3.tMm > 0) d.mm = xr3.tMm;
      if (ASS_REG_ID.papD.si(d, K) && assRegCtxAdm(d).itb && xr3.papD == null){
        var pM3 = assRegValN(d, 'pipeD');
        if (assRegPap0(d) > pM3 + 1e-9) xr3.papD = Math.floor(pM3 / 0.5 + 1e-7) * 0.5;
      }
    }
