    var xe4b = d.x && d.x.echappement;
    if (xe4b && xe4b.dL > 0) d.diam = xe4b.dL;
    /* V1.2.2 (ASSEMBLER L5) : des pistons a galerie gardent leurs gicleurs (un NON range tombe) ; de grandes ailettes demandent un entraxe
       regle d'au moins 1,60 alesage (M10 : un entraxe resserre apres coup les fait tomber) */
    var xf5b = d.x && d.x.finitions;
    if (xf5b && typeof xf5b === 'object'){
      if (xf5b.gicl === 'non' && d.p && d.p.pis === 'galerie') delete xf5b.gicl;
      if (xf5b.ail === 'grandes' && assRegFixe(d, 'entraxe') && d.x.bas.entraxe < 1.60 * d.bore - 1e-6) delete xf5b.ail;
      /* V1.2.2 (ASSEMBLER L5, verification) : une pompe a eau ELECTRIQUE n'a ni poulie ni arbre - l'helice mecanique ou visco tombe (annonce) */
      if (xf5b.pompeE === 'elec' && (xf5b.vent === 'meca' || xf5b.vent === 'visco')) delete xf5b.vent;
    }
