        var resM = reservoirSuitMoteur(v, avM.sig); if (resM) notesM.push(resM);     // V1.1.0.60
        var coupeM = couperSiFamilleChange(v, avM); if (coupeM) notesM.push(coupeM);
        majTypeEtNomMoteur(v);
