      "TRANSMISSION=INTEGRAL","POSITION_MOTEUR=AVANT","PNEU_TYPE=SPORT",
      "PNEU_TAILLE_AVANT=225/40R18","PNEU_TAILLE_ARRIERE=245/35R18","CX=0.33",
      "SUSPENSION=FERME",
      "RALENTI_TR=750","PUISSANCE_CH=340","PUISSANCE_TR=5500","PUISSANCE_TR_FIN=6000",
