      "RALENTI_TR=900","PUISSANCE_CH=400","PUISSANCE_TR=4300","PUISSANCE_TR_FIN=4700",
      "COUPLE_NM=780","COUPLE_TR=3000","COUPLE_TR_FIN=4000",
      "POIDS_KG=1010","RESERVOIR_L=40",
      "TURBO_TYPE=TURBO","TURBO_BAR=2.6","TURBO_MM=68","TURBO_VGT=NON","TURBO_STUTUTU=NON",
      "ZONE_ROUGE=5300","RUPTEUR=5600","BOITE_TYPE=MANUELLE",
      "HARD_CUT=OUI","FLAT_SHIFT=OUI","LAUNCH_RPM=3000",
