  /* ===== L'ELECTRIQUE A 2 RAPPORTS ET LA REPARTITION AU CATALOGUE (V1.0.89.364) =====
     D'apres les vraies voitures. Deux rapports sur l'essieu arriere : les RN E-Tran GT - la GT 646 les avait deja, les autres recoivent
     leur 1re a 52 % de la vitesse maxi. Repartition de puissance : Priuso, Priuso rechargeable, Yariso, CHRO, RAF-4, NX-Q et LX-C, dont
     le train epicycloidal tient lieu de courroie. */
  (function boitesElecAuCatalogue(){
    var P = { ELECTRIQUE_2: ['RNETGT', 'ETGT47', 'ETGT53', 'ETRSPE'],
              REPARTITION: ['TPRIUS4', 'TPRIUPL', 'TYARIHY', 'TCHRHYB', 'TRAV4HY', 'LNX300H', 'LLC500H'] };
    CATALOGUE.forEach(function(e){
      if (!e || typeof e.txt !== 'string') return;
      Object.keys(P).forEach(function(k){
        if (P[k].indexOf(e.code) < 0) return;
        var tx = /^BOITE_TYPE=/m.test(e.txt) ? e.txt.replace(/^BOITE_TYPE=.*$/m, 'BOITE_TYPE=' + k) : e.txt + '\nBOITE_TYPE=' + k;
        if (k === 'ELECTRIQUE_2') tx = tx.replace(/^VITESSES=\s*([0-9.]+)\s*$/m, function(l, vm){ return 'VITESSES=' + Math.round(parseFloat(vm) * 0.52) + ',' + Math.round(parseFloat(vm)); });
        e.txt = tx;
      });
    });
  })();
