    var r = lireSauvegarde(brut, true);     // V1.2.9 (CONCESSIONNAIRE, IMPORT BORNE) : le filet, sans bornes de taille (voir lireSauvegarde)
    if (!r.ok){ setStatus("RIEN A RESTAURER", true); return; }
    /* Les cles absentes du filet sont retirees (appliquerSauvegarde, avant de reposer le filet, dans le meme tout ou rien) :
       SON_STYLE_KEY (V1.2.5 (SONS, S1b) : il n'avait pas choisi : CLASSIQUE), ESSUIE_KEY (V1.2.8 (ESSUIE-GLACES) : il n'avait pas
       choisi : AUTO), DIRECTION_CLE (V1.2.8 (VOLANT) : il n'avait pas choisi : la barre).
       V1.2.9 (CONCESSIONNAIRE, IMPORT BORNE) : la meme regle pour TOUTE cle de la sauvegarde quand le filet a ete ecrit par CETTE
       version - une cle absente du filet n'existait pas avant l'import (l'import l'a apportee, ou le jeu l'a ecrite depuis) : sinon elle
       survivrait a ANNULER (ex. les favoris du concessionnaire, au lot 4). Un filet d'une version plus ancienne ne connaissait pas
       toutes les cles d'aujourd'hui : son silence ne dit pas qu'elles etaient absentes, on garde la regle des trois cles (celle d'avant). */
    var retirer = (r.version === VERSION) ? clesSauvegarde() : [SON_STYLE_KEY, ESSUIE_KEY, DIRECTION_CLE, FAV_INFINI_KEY];     // V1.2.9 (CONCESSIONNAIRE, FICHE) : une cle nee avec cette version : un filet plus ancien ne pouvait pas l'avoir
    if (appliquerSauvegarde(r.cles, retirer) < 0){ setStatus("ENREGISTREMENT IMPOSSIBLE - STOCKAGE REFUSE", true); return; }     // V1.2.9 (CONCESSIONNAIRE, IMPORT BORNE) : rien n'a change
    sauvegardeGelee = true;     // V1.2.9 (CONCESSIONNAIRE, IMPORT BORNE) : plus rien n'ecrit la partie jusqu'au rechargement
    setStatus("ETAT PRECEDENT RESTAURE - RECHARGEMENT");
