  if (els.btnCircPrec) bindTap(els.btnCircPrec, function(){ circCarPas(-1); });     // V1.0.89.420
  if (els.btnCircSuiv) bindTap(els.btnCircSuiv, function(){ circCarPas(1); });
  /* Le plan se tourne au doigt, et seulement au doigt : aucune boucle d'animation, donc rien ne consomme entre deux gestes. */
  if (els.circCarCv){
    els.circCarCv.addEventListener('pointerdown', function(ev){
      circCar.doigt = { id: ev.pointerId, x: ev.clientX };
      try { els.circCarCv.setPointerCapture(ev.pointerId); } catch (e){}
      ev.preventDefault(); ev.stopPropagation();
    });
    els.circCarCv.addEventListener('pointermove', function(ev){
      var d = circCar.doigt;
      if (!d || d.id !== ev.pointerId) return;
      circCar.yaw += (ev.clientX - d.x) * 0.012;
      d.x = ev.clientX;
      dessinerTrace3d(els.circCarCv, demoCircMontre(), circCar.yaw);     // V1.1.0.30 : la demo : le plan tourne sur le trace montre
      ev.preventDefault(); ev.stopPropagation();
    });
    ['pointerup', 'pointercancel'].forEach(function(nm){
      els.circCarCv.addEventListener(nm, function(ev){
        if (!circCar.doigt || circCar.doigt.id !== ev.pointerId) return;
        circCar.doigt = null;
        try { els.circCarCv.releasePointerCapture(ev.pointerId); } catch (e){}
        ev.stopPropagation();
      });
    });
  }
